"use client"

/**
 * Clean-room proposal flow. Wires the shell, dashboard, intake, deal tabs, and send toast.
 * Every label and record is a prop. This file does not name a product or ship a theme.
 */

import * as React from "react"
import { cn } from "@/lib/utils"
import type { FieldDef, MultiRecord, ViewConfig } from "@/lib/multi-view"
import {
  formatMoney,
  toggleScopeTask,
  type ClarifyQuestion,
  type EstimateLine,
  type PreflightItem,
  type PriceLine,
  type ProposalSection,
  type ProposalTabId,
  type ScopePhase,
} from "@/lib/proposal"
import { ProposalActivity } from "@/components/ui/proposal-activity"
import { ProposalAnalyze } from "@/components/ui/proposal-analyze"
import { ProposalClarify, type ProposalClarifyProps } from "@/components/ui/proposal-clarify"
import { ProposalDiscovery, type ProposalDiscoveryProps } from "@/components/ui/proposal-discovery"
import { ProposalDocument, type ProposalDocumentProps } from "@/components/ui/proposal-document"
import { ProposalEstimate, type CapacityCell, type ProposalEstimateProps } from "@/components/ui/proposal-estimate"
import { ProposalOpportunity, type OpportunityChoice, type OpportunityFile, type ProposalOpportunityProps } from "@/components/ui/proposal-opportunity"
import { ProposalRisks, type ProposalRisksProps } from "@/components/ui/proposal-risks"
import { ProposalScope, type ProposalScopeProps } from "@/components/ui/proposal-scope"
import { ProposalSend, type ProposalSendProps, type SendRecipient } from "@/components/ui/proposal-send"
import { ProposalSimilar, type ProposalSimilarProps } from "@/components/ui/proposal-similar"
import { ProposalSow, type ProposalSowProps } from "@/components/ui/proposal-sow"
import { ProposalWorkspace, type ProposalCrumb, type ProposalWorkspaceTab } from "@/components/ui/proposal-workspace"
import { ToastStack, ToastStackProvider, useToastStack } from "@/components/ui/toast-stack"
import { ViewKanban } from "@/components/ui/view-kanban"
import { ProposalDashboard, type ProposalDashboardProps } from "@/components/ui/proposal-dashboard"
import { ProposalShell, type ProposalShellProps } from "@/components/ui/proposal-shell"

export type ProposalBuilderCopy = {
  newOpportunity: string
  clarify: string
  apply: string
  continue: string
  approve: string
  send: string
  summaryTitle: string
  summaryHours: string
  summaryPrice: string
  sentTitle: string
  sentBody: string
  toastLabel: string
  analyzeLabel: string
  pipelineTitle: string
}

const COPY: ProposalBuilderCopy = {
  newOpportunity: "New opportunity",
  clarify: "Clarify",
  apply: "Apply answers",
  continue: "Continue",
  approve: "Approve scope",
  send: "Send",
  summaryTitle: "Summary",
  summaryHours: "Hours",
  summaryPrice: "Suggested price",
  sentTitle: "Proposal sent",
  sentBody: "The link is on its way.",
  toastLabel: "Notifications",
  analyzeLabel: "Reading the call",
  pipelineTitle: "Pipeline",
}

const ORDER: ProposalTabId[] = ["summary", "discovery", "scope", "similar", "estimate", "price", "risks", "proposal", "sow", "activity"]

export type ProposalBuilderProps = {
  shell: Omit<ProposalShellProps, "children" | "primaryLabel" | "onPrimary" | "primaryDisabled" | "activeHref" | "onNavigate">
  boardHref?: string
  pipelineHref?: string
  dashboard: Omit<ProposalDashboardProps, "onAction">
  clients: readonly OpportunityChoice[]
  projectTypes: readonly OpportunityChoice[]
  initialClient?: string
  initialType?: string
  initialFile?: OpportunityFile | null
  intake?: Omit<ProposalOpportunityProps, "open" | "onOpenChange" | "onAnalyze" | "clients" | "types" | "client" | "onClientChange" | "projectType" | "onProjectTypeChange" | "file" | "onFile">
  clarifyLabels?: Omit<ProposalClarifyProps, "questions" | "answers" | "onAnswer" | "baseHours" | "rate" | "hoursPerWeek" | "locale" | "currency">
  scopeLabels?: Omit<ProposalScopeProps, "phases" | "onToggle" | "exclusions" | "originLabels" | "locale">
  estimateLabels?: Omit<ProposalEstimateProps, "view" | "lines" | "capacity" | "priceMin" | "priceMax" | "price" | "onPriceChange" | "suggested" | "confidence" | "receipt" | "onUseSuggested" | "locale" | "currency">
  sendLabels?: Omit<ProposalSendProps, "open" | "onOpenChange" | "onSend" | "recipients" | "recipient" | "onRecipientChange" | "project" | "price" | "weeks" | "message" | "onMessageChange" | "link">
  opportunityTitle?: string
  analyzeLabel?: string
  analyzeMs?: number
  dealTitle: string
  crumbs: readonly ProposalCrumb[]
  tabs: readonly ProposalWorkspaceTab[]
  discovery: Omit<ProposalDiscoveryProps, "onClarify" | "onSeek">
  questions: readonly ClarifyQuestion[]
  baseHours: number
  rate: number
  hoursPerWeek?: number
  currency?: string
  phases: readonly ScopePhase[]
  exclusions: readonly { id: string; label: string }[]
  originLabels?: ProposalScopeOriginLabels
  similar: Omit<ProposalSimilarProps, "value" | "onValueChange">
  lines: readonly EstimateLine[]
  capacity: readonly CapacityCell[]
  priceMin: number
  priceMax: number
  suggested: number
  confidence: string
  receipt: readonly PriceLine[]
  risks: Omit<ProposalRisksProps, "selectedAction" | "onSelectAction" | "onApprove" | "approved">
  document: Omit<ProposalDocumentProps, "sections" | "onSectionsChange" | "preflight" | "onPreflight">
  initialSections: readonly ProposalSection[]
  initialPreflight: readonly PreflightItem[]
  sow: Omit<ProposalSowProps, "acknowledged" | "onAcknowledge">
  activity: React.ComponentProps<typeof ProposalActivity>
  recipients: readonly SendRecipient[]
  sendLink: string
  pipeline: {
    records: readonly MultiRecord[]
    fields: readonly FieldDef[]
    config: ViewConfig
  }
  copy?: Partial<ProposalBuilderCopy>
  contained?: boolean
  className?: string
}

type ProposalScopeOriginLabels = React.ComponentProps<typeof ProposalScope>["originLabels"]

function nextTab(id: ProposalTabId): ProposalTabId {
  const index = ORDER.indexOf(id)
  return ORDER[Math.min(ORDER.length - 1, index + 1)] ?? id
}

export function ProposalBuilder(props: ProposalBuilderProps) {
  return (
    <ToastStackProvider>
      <ToastStack position="bottom-right" contained={props.contained} label={props.copy?.toastLabel ?? COPY.toastLabel} />
      <ProposalBuilderBody {...props} />
    </ToastStackProvider>
  )
}

function ProposalBuilderBody({
  shell,
  boardHref = "#board",
  pipelineHref = "#pipeline",
  dashboard,
  clients,
  projectTypes,
  initialClient,
  initialType,
  initialFile = null,
  intake,
  clarifyLabels,
  scopeLabels,
  estimateLabels,
  sendLabels,
  opportunityTitle,
  analyzeLabel,
  analyzeMs = 700,
  dealTitle,
  crumbs,
  tabs,
  discovery,
  questions,
  baseHours,
  rate,
  hoursPerWeek = 30,
  currency = "USD",
  phases,
  exclusions,
  originLabels,
  similar,
  lines,
  capacity,
  priceMin,
  priceMax,
  suggested,
  confidence,
  receipt,
  risks,
  document,
  initialSections,
  initialPreflight,
  sow,
  activity,
  recipients,
  sendLink,
  pipeline,
  copy,
  contained,
  className,
}: ProposalBuilderProps) {
  const text = { ...COPY, ...copy }
  const toast = useToastStack()
  const [screen, setScreen] = React.useState<"dashboard" | "pipeline" | "analyzing" | "deal">("dashboard")
  const [tab, setTab] = React.useState<ProposalTabId>("summary")
  const [clarify, setClarify] = React.useState(false)
  const [intakeOpen, setIntakeOpen] = React.useState(false)
  const [sendOpen, setSendOpen] = React.useState(false)
  const [client, setClient] = React.useState(initialClient)
  const [projectType, setProjectType] = React.useState(initialType)
  const [file, setFile] = React.useState<OpportunityFile | null>(initialFile)
  const [answers, setAnswers] = React.useState<Record<string, string>>({})
  const [scope, setScope] = React.useState<ScopePhase[]>(() => phases.map((phase) => ({ ...phase, tasks: phase.tasks.map((task) => ({ ...task })) })))
  const [similarId, setSimilarId] = React.useState(similar.projects[0]?.id)
  const [price, setPrice] = React.useState(suggested)
  const [riskAction, setRiskAction] = React.useState<string>()
  const [approved, setApproved] = React.useState(false)
  const [sections, setSections] = React.useState<ProposalSection[]>(() => initialSections.map((section) => ({ ...section })))
  const [preflight, setPreflight] = React.useState<PreflightItem[]>(() => initialPreflight.map((item) => ({ ...item })))
  const [ack, setAck] = React.useState(false)
  const [recipient, setRecipient] = React.useState(recipients[0]?.value)
  const [message, setMessage] = React.useState("")
  const [records, setRecords] = React.useState<MultiRecord[]>(() => pipeline.records.map((record) => ({ ...record })))

  React.useEffect(() => {
    if (screen !== "analyzing") return
    const timer = window.setTimeout(() => {
      setScreen("deal")
      setTab("discovery")
    }, analyzeMs)
    return () => window.clearTimeout(timer)
  }, [analyzeMs, screen])

  const primary = (() => {
    if (screen !== "deal") return { label: text.newOpportunity, disabled: screen === "analyzing", run: () => setIntakeOpen(true) }
    if (clarify) return { label: text.apply, disabled: false, run: () => { setClarify(false); setTab("scope") } }
    if (tab === "discovery") return { label: text.clarify, disabled: false, run: () => setClarify(true) }
    if (tab === "risks" && !approved) return { label: text.approve, disabled: false, run: () => setApproved(true) }
    if (tab === "proposal") return { label: text.send, disabled: false, run: () => setSendOpen(true) }
    return { label: text.continue, disabled: false, run: () => setTab(nextTab(tab)) }
  })()

  const hours = scope.reduce((sum, phase) => sum + phase.tasks.reduce((inner, task) => inner + (task.included ? task.hours : 0), 0), 0)

  return (
    <div data-slot="proposal-builder" className={cn("min-w-0", className)}>
      <ProposalShell
        {...shell}
        contained={contained ?? shell.contained}
        activeHref={screen === "pipeline" ? pipelineHref : boardHref}
        primaryLabel={primary.label}
        primaryDisabled={primary.disabled}
        onPrimary={primary.run}
        onNavigate={(href) => {
          if (href === pipelineHref) setScreen("pipeline")
          if (href === boardHref) setScreen("dashboard")
        }}
      >
        {screen === "dashboard" ? <ProposalDashboard {...dashboard} onAction={() => setIntakeOpen(true)} /> : null}
        {screen === "pipeline" ? (
          <section aria-label={text.pipelineTitle} className="min-w-0">
            <h1 className="mb-3 text-xl font-medium">{text.pipelineTitle}</h1>
            <ViewKanban
              records={records}
              fields={pipeline.fields}
              config={pipeline.config}
              locale={dashboard.locale}
              cardLayout="summary"
              onOpen={() => {
                setScreen("deal")
                setTab("summary")
              }}
              onMove={(id, patch) => {
                setRecords((current) => current.map((record) => (record.id === id ? { ...record, ...patch } : record)))
              }}
            />
          </section>
        ) : null}
        {screen === "analyzing" ? <ProposalAnalyze label={analyzeLabel ?? text.analyzeLabel} /> : null}
        {screen === "deal" ? (
          <ProposalWorkspace crumbs={crumbs} tabs={tabs} value={clarify ? "discovery" : tab} onValueChange={(id) => { setClarify(false); setTab(id as ProposalTabId) }} title={dealTitle}>
            {clarify ? (
              <ProposalClarify
                {...clarifyLabels}
                questions={questions}
                answers={answers}
                onAnswer={(id, value) => setAnswers((current) => ({ ...current, [id]: value }))}
                baseHours={baseHours}
                rate={rate}
                hoursPerWeek={hoursPerWeek}
                locale={dashboard.locale}
                currency={currency}
              />
            ) : null}
            {!clarify && tab === "summary" ? (
              <div className="grid gap-3 sm:grid-cols-3">
                <SummaryCard label={text.summaryTitle} value={dealTitle} />
                <SummaryCard label={text.summaryHours} value={String(hours)} />
                <SummaryCard label={text.summaryPrice} value={formatMoney(price, dashboard.locale, currency)} />
              </div>
            ) : null}
            {!clarify && tab === "discovery" ? <ProposalDiscovery {...discovery} onClarify={() => setClarify(true)} /> : null}
            {!clarify && tab === "scope" ? (
              <ProposalScope {...scopeLabels} phases={scope} exclusions={exclusions} originLabels={originLabels} locale={dashboard.locale} onToggle={(id) => setScope((current) => toggleScopeTask(current, id))} />
            ) : null}
            {!clarify && tab === "similar" ? <ProposalSimilar {...similar} value={similarId} onValueChange={setSimilarId} locale={dashboard.locale} currency={currency} /> : null}
            {!clarify && tab === "estimate" ? (
              <ProposalEstimate {...estimateLabels} view="effort" lines={lines} capacity={capacity} priceMin={priceMin} priceMax={priceMax} price={price} suggested={suggested} confidence={confidence} receipt={receipt} locale={dashboard.locale} currency={currency} onPriceChange={setPrice} onUseSuggested={() => setPrice(suggested)} />
            ) : null}
            {!clarify && tab === "price" ? (
              <ProposalEstimate {...estimateLabels} view="price" lines={lines} capacity={capacity} priceMin={priceMin} priceMax={priceMax} price={price} suggested={suggested} confidence={confidence} receipt={receipt} locale={dashboard.locale} currency={currency} onPriceChange={setPrice} onUseSuggested={() => setPrice(suggested)} />
            ) : null}
            {!clarify && tab === "risks" ? (
              <ProposalRisks {...risks} selectedAction={riskAction} onSelectAction={setRiskAction} approved={approved} onApprove={() => setApproved(true)} />
            ) : null}
            {!clarify && tab === "proposal" ? (
              <ProposalDocument
                {...document}
                sections={sections}
                onSectionsChange={setSections}
                preflight={preflight}
                onPreflight={(id, done) => setPreflight((current) => current.map((item) => (item.id === id ? { ...item, done } : item)))}
              />
            ) : null}
            {!clarify && tab === "sow" ? <ProposalSow {...sow} acknowledged={ack} onAcknowledge={setAck} /> : null}
            {!clarify && tab === "activity" ? <ProposalActivity {...activity} /> : null}
          </ProposalWorkspace>
        ) : null}
      </ProposalShell>
      <ProposalOpportunity
        {...intake}
        open={intakeOpen}
        onOpenChange={setIntakeOpen}
        title={opportunityTitle}
        clients={clients}
        client={client}
        onClientChange={setClient}
        types={projectTypes}
        projectType={projectType}
        onProjectTypeChange={setProjectType}
        file={file}
        onFile={setFile}
        onAnalyze={() => {
          setIntakeOpen(false)
          setScreen("analyzing")
        }}
      />
      <ProposalSend
        {...sendLabels}
        open={sendOpen}
        onOpenChange={setSendOpen}
        recipients={recipients}
        recipient={recipient}
        onRecipientChange={setRecipient}
        project={dealTitle}
        price={formatMoney(price, dashboard.locale, currency)}
        weeks={String(risks.historicalWeeks)}
        message={message}
        onMessageChange={setMessage}
        link={sendLink}
        onSend={() => {
          setSendOpen(false)
          toast.toast({ type: "success", title: text.sentTitle, description: text.sentBody })
        }}
      />
    </div>
  )
}

function SummaryCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0 rounded-xl border border-border bg-card p-3">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className="mt-1 truncate text-sm font-medium">{value}</p>
    </div>
  )
}

"use client"

/** Clean-room proposal dialog frame. No theme of its own. */

import * as React from "react"
import { Dialog as DialogPrimitive } from "radix-ui"
import { motion, useReducedMotion } from "motion/react"
import { XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogDescription,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
} from "@/components/ui/dialog"
import { cn } from "@/lib/utils"

export type ProposalMotionDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  children: React.ReactNode
  className?: string
  closeLabel?: string
}

export function ProposalMotionDialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  className,
  closeLabel = "Close",
}: ProposalMotionDialogProps) {
  const reduced = !!useReducedMotion()
  const titleId = React.useId()
  const descriptionId = React.useId()

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogPortal>
        <DialogOverlay className="duration-200" />
        <DialogPrimitive.Content
          data-slot="proposal-dialog"
          data-motion={reduced ? "reduced" : "full"}
          aria-labelledby={titleId}
          aria-describedby={description ? descriptionId : undefined}
          className={cn(
            "fixed top-1/2 left-1/2 z-50 w-[min(100%-2rem,36rem)] max-h-[min(100dvh-2rem,40rem)] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-xl bg-popover p-4 text-sm text-popover-foreground shadow-lg ring-1 ring-foreground/10 outline-none",
            className,
          )}
        >
          <motion.div
            className="grid gap-4"
            initial={reduced ? false : { opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: reduced ? 0 : 0.2 }}
          >
            <div className="flex items-start justify-between gap-3 pe-8">
              <div className="min-w-0">
                <DialogTitle id={titleId} className="text-base">
                  {title}
                </DialogTitle>
                {description ? (
                  <DialogDescription id={descriptionId} className="mt-1">
                    {description}
                  </DialogDescription>
                ) : null}
              </div>
            </div>
            <DialogPrimitive.Close asChild>
              <Button type="button" variant="ghost" size="icon-sm" className="absolute top-2 right-2" aria-label={closeLabel}>
                <XIcon />
              </Button>
            </DialogPrimitive.Close>
            {children}
          </motion.div>
        </DialogPrimitive.Content>
      </DialogPortal>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import {
  ChevronDown,
  ChevronRight,
  ChevronsUpDown,
  PanelLeftIcon,
  Search,
} from "lucide-react"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Sidebar,
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type RailDot =
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "primary"
  | "muted"
  | "destructive"

export type RailLinkRenderProps = {
  href: string
  className?: string
  children: React.ReactNode
  "aria-current"?: "page"
  onClick?: (event: React.MouseEvent<HTMLElement>) => void
}

export type RailLink = {
  id: string
  label: string
  href?: string
  icon?: React.ReactNode
  badge?: string | number
  /** Alert counts use the destructive tone. */
  badgeTone?: "default" | "alert"
  dot?: RailDot
  disabled?: boolean
  /** Single element, such as a Next.js or React Router link. */
  asChild?: React.ReactElement
}

export type RailEntry = RailLink & {
  /** When set, the entry is a collapsible group of sub-items. */
  items?: readonly RailLink[]
  defaultOpen?: boolean
}

export type RailScope = {
  label: string
  options: readonly { value: string; label: string }[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
}

export type RailFooterLink = {
  id: string
  label: string
  href?: string
  count?: number
  onSelect?: () => void
}

export type RailNavGroup = {
  id: string
  /** Omit for a flat list with no heading. */
  label?: string
  items: readonly RailEntry[]
}

export type RailSection = {
  id: string
  label: string
  icon: React.ReactNode
  badge?: string | number
  /** Secondary sections sit above the avatar. */
  placement?: "primary" | "secondary"
  nav: readonly RailNavGroup[]
  /** Extra control beside the section title, such as add or a menu. */
  action?: React.ReactNode
  /** Optional leading row, for example every open record and its count. */
  all?: { label: string; href?: string; count?: number }
}

export type RailWorkspaceOption = {
  id: string
  name: string
  subtitle?: string
  logo?: React.ReactNode
}

export type RailWorkspace = {
  name: string
  subtitle?: string
  logo?: React.ReactNode
  options?: readonly RailWorkspaceOption[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  status?: "online" | "away" | "offline"
}

export type RailUser = {
  name: string
  email?: string
  avatarUrl?: string
}

export type RailSidebarProps = {
  sections: readonly RailSection[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  /** Href of the current page. Matching links get aria-current="page". */
  activeHref?: string
  renderLink?: (props: RailLinkRenderProps) => React.ReactElement
  onNavigate?: (href: string) => void
  workspace?: RailWorkspace
  user?: RailUser
  /** Menu body for the user dropdown. Render menu items here. */
  footerSlot?: React.ReactNode
  onSearch?: (query: string) => void
  onOpenCommand?: () => void
  searchPlaceholder?: string
  /** One collapsible entry open at a time, or several. */
  type?: "single" | "multiple"
  /** Passed to the shadcn sidebar. "icon" keeps the rail and hides the panel. */
  collapsible?: "offcanvas" | "icon" | "none"
  /** In-flow layout for thumbnails, tests, and narrow containers. */
  contained?: boolean
  /** row is the default card highlight. pill uses an inverted active item. */
  itemStyle?: "row" | "pill"
  /** panel hides the icon rail and shows only the link column. */
  layout?: "rail" | "panel"
  showSearch?: boolean
  showSectionTitle?: boolean
  brand?: React.ReactNode
  /** Replaces the built-in workspace row. */
  workspaceSlot?: React.ReactNode
  /** Renders above the user card. */
  panelFooter?: React.ReactNode
  mark?: React.ReactNode
  markLabel?: string
  children?: React.ReactNode
  className?: string
  railClassName?: string
  panelClassName?: string
  itemClassName?: string
  groupClassName?: string
  headerClassName?: string
  footerClassName?: string
  searchClassName?: string
  insetClassName?: string
  railLabel?: string
  panelLabel?: string
  searchLabel?: string
  commandLabel?: string
  collapseLabel?: string
  expandLabel?: string
  scope?: RailScope
  footerLinks?: readonly RailFooterLink[]
}

const DOT_CLASS: Record<RailDot, string> = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
  primary: "bg-primary",
  muted: "bg-muted-foreground",
  destructive: "bg-destructive",
}

function useControllable(value: string | undefined, defaultValue: string | undefined, onChange?: (next: string) => void) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue ?? "")
  const selected = value ?? uncontrolled
  const setSelected = React.useCallback(
    (next: string) => {
      if (value === undefined) setUncontrolled(next)
      onChange?.(next)
    },
    [onChange, value],
  )
  return [selected, setSelected] as const
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

function ItemBody({ item, className, active = false, pill = false }: { item: RailLink; className?: string; active?: boolean; pill?: boolean }) {
  return (
    <>
      {item.dot ? (
        <span className={cn("size-2 shrink-0 rounded-full", DOT_CLASS[item.dot])} aria-hidden />
      ) : item.icon ? (
        <span className="text-muted-foreground [&_svg]:size-4" aria-hidden>
          {item.icon}
        </span>
      ) : null}
      <span className={cn("min-w-0 flex-1 truncate text-start", className)}>{item.label}</span>
      {item.badge != null && item.badge !== "" ? (
        <Badge
          variant="secondary"
          className={cn(
            "ms-auto tabular-nums",
            item.badgeTone === "alert" && "bg-destructive/10 text-destructive",
            pill && active && "bg-primary text-primary-foreground",
          )}
        >
          {item.badge}
        </Badge>
      ) : null}
    </>
  )
}

function RailAnchor({
  item,
  active,
  className,
  renderLink,
  onNavigate,
  pill = false,
}: {
  item: RailLink
  active: boolean
  className: string
  renderLink?: RailSidebarProps["renderLink"]
  onNavigate?: (href: string) => void
  pill?: boolean
}) {
  const current = active ? "page" : undefined
  const onClick = (event: React.MouseEvent<HTMLElement>) => {
    if (item.disabled) {
      event.preventDefault()
      return
    }
    if (item.href && onNavigate) {
      event.preventDefault()
      onNavigate(item.href)
    }
  }

  if (item.asChild) {
    return (
      <Slot.Root
        className={className}
        aria-current={current}
        aria-disabled={item.disabled || undefined}
        onClick={onClick}
      >
        {React.cloneElement(item.asChild, undefined, <ItemBody item={item} active={active} pill={pill} />)}
      </Slot.Root>
    )
  }

  if (item.href && renderLink) {
    return renderLink({
      href: item.href,
      className,
      "aria-current": current,
      onClick,
      children: <ItemBody item={item} active={active} pill={pill} />,
    })
  }

  if (item.href) {
    return (
      <a
        href={item.href}
        className={className}
        aria-current={current}
        aria-disabled={item.disabled || undefined}
        onClick={onClick}
      >
        <ItemBody item={item} active={active} pill={pill} />
      </a>
    )
  }

  return (
    <button type="button" className={className} disabled={item.disabled} aria-current={current} onClick={onClick}>
      <ItemBody item={item} active={active} pill={pill} />
    </button>
  )
}

function entryOpen(type: "single" | "multiple", single: string | null, many: readonly string[], id: string) {
  return type === "single" ? single === id : many.includes(id)
}

function RailColumns({
  sections,
  sectionId,
  onSectionChange,
  activeHref,
  renderLink,
  onNavigate,
  workspace,
  user,
  footerSlot,
  onSearch,
  onOpenCommand,
  searchPlaceholder,
  type,
  panelVisible,
  onTogglePanel,
  mark,
  markLabel,
  className,
  railClassName,
  panelClassName,
  itemClassName,
  groupClassName,
  headerClassName,
  footerClassName,
  searchClassName,
  railLabel,
  panelLabel,
  searchLabel,
  commandLabel,
  collapseLabel,
  expandLabel,
  showCollapse,
  scope,
  footerLinks,
  itemStyle = "row",
  layout = "rail",
  showSearch = true,
  showSectionTitle = true,
  brand,
  workspaceSlot,
  panelFooter,
}: {
  sections: readonly RailSection[]
  sectionId: string
  onSectionChange: (id: string) => void
  panelVisible: boolean
  onTogglePanel?: () => void
  showCollapse: boolean
} & Pick<
  RailSidebarProps,
  | "activeHref"
  | "renderLink"
  | "onNavigate"
  | "workspace"
  | "user"
  | "footerSlot"
  | "onSearch"
  | "onOpenCommand"
  | "searchPlaceholder"
  | "type"
  | "mark"
  | "markLabel"
  | "className"
  | "railClassName"
  | "panelClassName"
  | "itemClassName"
  | "groupClassName"
  | "headerClassName"
  | "footerClassName"
  | "searchClassName"
  | "railLabel"
  | "panelLabel"
  | "searchLabel"
  | "commandLabel"
  | "collapseLabel"
  | "expandLabel"
  | "scope"
  | "footerLinks"
  | "itemStyle"
  | "layout"
  | "showSearch"
  | "showSectionTitle"
  | "brand"
  | "workspaceSlot"
  | "panelFooter"
>) {
  const accordion = type ?? "single"
  const railRef = React.useRef<HTMLElement>(null)
  const section = sections.find((item) => item.id === sectionId) ?? sections[0]
  const primary = sections.filter((item) => item.placement !== "secondary")
  const secondary = sections.filter((item) => item.placement === "secondary")
  const [workspaceId, setWorkspaceId] = useControllable(
    workspace?.value,
    workspace?.defaultValue ?? workspace?.options?.[0]?.id,
    workspace?.onValueChange,
  )
  const activeWorkspace =
    workspace?.options?.find((option) => option.id === workspaceId) ??
    (workspace
      ? { id: workspaceId, name: workspace.name, subtitle: workspace.subtitle, logo: workspace.logo }
      : undefined)

  const sectionKey = section?.id ?? ""
  const defaultOpenIds = section?.nav.flatMap((group) =>
    group.items.filter((item) => item.defaultOpen && item.items?.length).map((item) => item.id),
  ) ?? []
  const [openBySection, setOpenBySection] = React.useState<Record<string, { single: string | null; many: string[] }>>({})
  const openState = openBySection[sectionKey] ?? {
    single: defaultOpenIds[0] ?? null,
    many: defaultOpenIds,
  }
  const singleOpen = openState.single
  const manyOpen = openState.many

  React.useEffect(() => {
    if (!onOpenCommand) return
    const onKey = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey)) return
      event.preventDefault()
      onOpenCommand()
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onOpenCommand])

  function toggleEntry(id: string) {
    setOpenBySection((current) => {
      const previous = current[sectionKey] ?? {
        single: defaultOpenIds[0] ?? null,
        many: defaultOpenIds,
      }
      if (accordion === "single") {
        return { ...current, [sectionKey]: { ...previous, single: previous.single === id ? null : id } }
      }
      const many = previous.many.includes(id) ? previous.many.filter((item) => item !== id) : [...previous.many, id]
      return { ...current, [sectionKey]: { ...previous, many } }
    })
  }

  function onRailKeyDown(event: React.KeyboardEvent<HTMLElement>) {
    const keys = ["ArrowDown", "ArrowUp", "Home", "End"]
    if (!keys.includes(event.key)) return
    const buttons = [...(railRef.current?.querySelectorAll<HTMLButtonElement>("[data-rail-section]") ?? [])]
    if (!buttons.length) return
    event.preventDefault()
    const index = buttons.findIndex((button) => button === document.activeElement)
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? buttons.length - 1
          : event.key === "ArrowDown"
            ? (Math.max(index, 0) + 1) % buttons.length
            : (index <= 0 ? buttons.length : index) - 1
    buttons[next]?.focus()
  }

  const itemClass = cn(
    "flex w-full min-w-0 items-center gap-2 px-2 py-1.5 text-sm hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
    itemStyle === "pill"
      ? "rounded-full aria-[current=page]:bg-foreground aria-[current=page]:text-background"
      : "rounded-md aria-[current=page]:bg-card aria-[current=page]:font-medium aria-[current=page]:shadow-sm",
    itemClassName,
  )
  const pill = itemStyle === "pill"

  const userMenu = user ? (
    <DropdownMenuContent align="start" className="w-56">
      <DropdownMenuLabel className="font-normal">
        <span className="block truncate text-sm font-medium">{user.name}</span>
        {user.email ? <span className="block truncate text-xs text-muted-foreground">{user.email}</span> : null}
      </DropdownMenuLabel>
      {footerSlot}
    </DropdownMenuContent>
  ) : null

  return (
    <TooltipProvider>
      <div className={cn("flex h-full min-h-0 w-full min-w-0", className)}>
        <nav
          ref={railRef}
          hidden={layout === "panel"}
          aria-label={railLabel ?? "Sections"}
          onKeyDown={onRailKeyDown}
          className={cn(
            "flex w-12 shrink-0 flex-col items-center gap-1 border-e border-border bg-sidebar px-1.5 py-2 text-sidebar-foreground",
            railClassName,
          )}
        >
          <div className="relative mb-1">
            <div className="grid size-8 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">
              {mark ?? (markLabel ?? workspace?.name ?? "A").slice(0, 1)}
            </div>
            {workspace?.status ? <StatusDot status={workspace.status} /> : null}
          </div>
          <div className="flex w-full flex-col items-center gap-1">
            {primary.map((item) => (
              <RailSectionButton
                key={item.id}
                item={item}
                pressed={item.id === section?.id}
                onSelect={onSectionChange}
              />
            ))}
          </div>
          <div className="mt-auto flex w-full flex-col items-center gap-1">
            {showCollapse && onTogglePanel ? (
              <button
                type="button"
                onClick={onTogglePanel}
                aria-pressed={panelVisible}
                aria-label={panelVisible ? (collapseLabel ?? "Collapse panel") : (expandLabel ?? "Expand panel")}
                className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <PanelLeftIcon className="size-4" />
              </button>
            ) : null}
            {secondary.map((item) => (
              <RailSectionButton
                key={item.id}
                item={item}
                pressed={item.id === section?.id}
                onSelect={onSectionChange}
              />
            ))}
            {user ? (
              panelVisible ? (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="mt-1 inline-flex">
                      <Avatar size="sm">
                        {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                        <AvatarFallback>{initials(user.name)}</AvatarFallback>
                      </Avatar>
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>{user.name}</TooltipContent>
                </Tooltip>
              ) : (
                <DropdownMenu>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <DropdownMenuTrigger
                        aria-label={user.name}
                        className="mt-1 rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        <Avatar size="sm">
                          {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                          <AvatarFallback>{initials(user.name)}</AvatarFallback>
                        </Avatar>
                      </DropdownMenuTrigger>
                    </TooltipTrigger>
                    <TooltipContent>{user.name}</TooltipContent>
                  </Tooltip>
                  {userMenu}
                </DropdownMenu>
              )
            ) : null}
          </div>
        </nav>

        {panelVisible ? (
          <div
            id="rail-panel"
            role="region"
            aria-label={panelLabel ?? section?.label ?? "Navigation"}
            className={cn("flex min-w-0 flex-1 flex-col bg-card", panelClassName)}
          >
            <div className={cn("flex flex-col gap-2 p-3", headerClassName)}>
              {brand}
              {workspaceSlot ?? (workspace && activeWorkspace ? (
                workspace.options && workspace.options.length > 0 ? (
                  <DropdownMenu>
                    <DropdownMenuTrigger
                      className="flex w-full items-center gap-2 rounded-lg bg-muted px-2 py-2 text-start hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <WorkspaceMark logo={activeWorkspace.logo} name={activeWorkspace.name} status={workspace.status} />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-medium">{activeWorkspace.name}</span>
                        {activeWorkspace.subtitle ? (
                          <span className="block truncate text-xs text-muted-foreground">{activeWorkspace.subtitle}</span>
                        ) : null}
                      </span>
                      <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-64">
                      {workspace.options.map((option) => (
                        <DropdownMenuItem key={option.id} onSelect={() => setWorkspaceId(option.id)} className="gap-2">
                          <WorkspaceMark logo={option.logo} name={option.name} />
                          <span className="min-w-0">
                            <span className="block truncate">{option.name}</span>
                            {option.subtitle ? (
                              <span className="block truncate text-xs text-muted-foreground">{option.subtitle}</span>
                            ) : null}
                          </span>
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                ) : (
                  <div className="relative flex items-center gap-2 rounded-lg bg-muted px-2 py-2">
                    <WorkspaceMark logo={workspace.logo} name={workspace.name} status={workspace.status} />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-medium">{workspace.name}</span>
                      {workspace.subtitle ? (
                        <span className="block truncate text-xs text-muted-foreground">{workspace.subtitle}</span>
                      ) : null}
                    </span>
                  </div>
                )
              ) : null)}

              {showSectionTitle ? (
              <div className="flex items-center justify-between gap-2 px-1">
                <h2 className="min-w-0 truncate text-sm font-medium">{section?.label}</h2>
                {section?.action}
              </div>
              ) : null}
              {scope ? <ScopeToggle scope={scope} /> : null}

              {showSearch ? <div className={cn("relative", searchClassName)}>
                <Search className="pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type="search"
                  aria-label={searchLabel ?? "Search"}
                  aria-keyshortcuts="Meta+K"
                  placeholder={searchPlaceholder ?? "Search or ask AI…"}
                  onChange={(event) => onSearch?.(event.target.value)}
                  className="ps-8 pe-14 [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
                />
                {onOpenCommand ? (
                  <button
                    type="button"
                    onClick={onOpenCommand}
                    aria-label={commandLabel ?? "Open command menu"}
                    className="absolute end-1.5 top-1/2 -translate-y-1/2 rounded-md border border-border bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <kbd>⌘K</kbd>
                  </button>
                ) : (
                  <kbd className="pointer-events-none absolute end-2 top-1/2 -translate-y-1/2 rounded-md border border-border bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
                    ⌘K
                  </kbd>
                )}
              </div> : null}
            </div>

            <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
              {section?.all ? (
                <RailAnchor
                  item={{ id: `${section.id}-all`, label: section.all.label, href: section.all.href ?? "#", badge: section.all.count }}
                  active={Boolean(section.all.href && section.all.href === activeHref)}
                  className={cn(itemClass, "mb-1")}
                  renderLink={renderLink}
                  onNavigate={onNavigate}
                  pill={pill}
                />
              ) : null}
              {section?.nav.map((group) => (
                <div key={group.id} className={cn("mb-2", groupClassName)}>
                  {group.label ? (
                    <p className="truncate px-2 py-1.5 text-xs font-medium text-muted-foreground">{group.label}</p>
                  ) : null}
                  <ul className="flex flex-col gap-0.5">
                    {group.items.map((item) => {
                      const nested = item.items ?? []
                      const open = nested.length > 0 && entryOpen(accordion, singleOpen, manyOpen, item.id)
                      const active = Boolean(item.href && item.href === activeHref)
                      return (
                        <li key={item.id}>
                          {nested.length > 0 ? (
                            <button
                              type="button"
                              aria-expanded={open}
                              aria-controls={`${item.id}-items`}
                              onClick={() => toggleEntry(item.id)}
                              className={itemClass}
                            >
                              {open ? (
                                <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
                              ) : (
                                <ChevronRight className="size-4 shrink-0 text-muted-foreground rtl:rotate-180" />
                              )}
                              <ItemBody item={item} pill={pill} />
                            </button>
                          ) : (
                            <RailAnchor
                              item={item}
                              active={active}
                              className={itemClass}
                              renderLink={renderLink}
                              onNavigate={onNavigate}
                              pill={pill}
                            />
                          )}
                          {nested.length > 0 ? (
                            <div
                              id={`${item.id}-items`}
                              className={cn(
                                "grid transition-[grid-template-rows,opacity] duration-200 ease-out motion-reduce:transition-none",
                                open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
                              )}
                              inert={open ? undefined : true}
                            >
                              <div className="overflow-hidden">
                                <ul className="relative ms-4 flex flex-col gap-0.5 border-s border-border py-0.5 ps-2">
                                  {nested.map((child) => (
                                    <li key={child.id} className="relative before:absolute before:-start-2 before:top-1/2 before:h-px before:w-2 before:bg-border">
                                      <RailAnchor
                                        item={child}
                                        active={Boolean(child.href && child.href === activeHref)}
                                        className={itemClass}
                                        renderLink={renderLink}
                                        onNavigate={onNavigate}
                                        pill={pill}
                                      />
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            </div>
                          ) : null}
                        </li>
                      )
                    })}
                  </ul>
                </div>
              ))}
              {!section?.nav.length ? (
                <p className="px-2 py-3 text-sm text-muted-foreground">No links</p>
              ) : null}
            </div>

            {footerLinks?.length ? (
              <ul className="border-t border-border px-2 py-2">
                {footerLinks.map((link) => (
                  <li key={link.id}>
                    <RailAnchor
                      item={{ id: link.id, label: link.label, href: link.href ?? "#", badge: link.count }}
                      active={Boolean(link.href && link.href === activeHref)}
                      className={itemClass}
                      renderLink={renderLink}
                      pill={pill}
                      onNavigate={(href) => {
                        link.onSelect?.()
                        onNavigate?.(href)
                      }}
                    />
                  </li>
                ))}
              </ul>
            ) : null}
            {panelFooter ? <div className="px-2 pb-2">{panelFooter}</div> : null}
            {user ? (
              <div className={cn("border-t border-border p-2", footerClassName)}>
                <DropdownMenu>
                  <DropdownMenuTrigger className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-start hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
                    <Avatar size="sm">
                      {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                      <AvatarFallback>{initials(user.name)}</AvatarFallback>
                    </Avatar>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-medium">{user.name}</span>
                      {user.email ? <span className="block truncate text-xs text-muted-foreground">{user.email}</span> : null}
                    </span>
                    <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
                  </DropdownMenuTrigger>
                  {userMenu}
                </DropdownMenu>
              </div>
            ) : footerSlot ? (
              <div className={cn("border-t border-border p-2", footerClassName)}>{footerSlot}</div>
            ) : null}
          </div>
        ) : null}
      </div>
    </TooltipProvider>
  )
}

function WorkspaceMark({ logo, name, status }: { logo?: React.ReactNode; name: string; status?: RailWorkspace["status"] }) {
  return (
    <span className="relative grid size-8 shrink-0 place-items-center rounded-full bg-background text-xs font-semibold">
      {logo ?? initials(name).slice(0, 1)}
      {status ? <StatusDot status={status} /> : null}
    </span>
  )
}

function StatusDot({ status }: { status: NonNullable<RailWorkspace["status"]> }) {
  return (
    <span
      data-status={status}
      className={cn(
        "absolute end-0 bottom-0 size-2 rounded-full ring-2 ring-background",
        status === "online" && "bg-chart-2",
        status === "away" && "bg-chart-4",
        status === "offline" && "bg-muted-foreground",
      )}
      aria-hidden
    />
  )
}

function ScopeToggle({ scope }: { scope: RailScope }) {
  const [internal, setInternal] = React.useState(scope.defaultValue ?? scope.options[0]?.value ?? "")
  const selected = scope.value ?? internal
  function choose(value: string) {
    if (scope.value === undefined) setInternal(value)
    scope.onValueChange?.(value)
  }
  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!["ArrowRight", "ArrowLeft", "ArrowDown", "ArrowUp"].includes(event.key)) return
    event.preventDefault()
    const index = Math.max(0, scope.options.findIndex((option) => option.value === selected))
    const delta = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1
    const next = scope.options[(index + delta + scope.options.length) % scope.options.length]
    if (!next) return
    choose(next.value)
    event.currentTarget.querySelector<HTMLElement>(`[data-value="${next.value}"]`)?.focus()
  }
  return (
    <div role="radiogroup" aria-label={scope.label} onKeyDown={onKeyDown} className="flex gap-0.5 rounded-full bg-muted p-0.5">
      {scope.options.map((option) => {
        const checked = option.value === selected
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            onClick={() => choose(option.value)}
            data-value={option.value}
            className={cn("min-w-0 flex-1 rounded-full px-2 py-1 text-xs", checked ? "bg-card text-foreground shadow-sm" : "text-muted-foreground")}
          >
            {option.label}
          </button>
        )
      })}
    </div>
  )
}

function RailSectionButton({
  item,
  pressed,
  onSelect,
}: {
  item: RailSection
  pressed: boolean
  onSelect: (id: string) => void
}) {
  const label = item.badge != null && item.badge !== "" ? `${item.label}, ${item.badge}` : item.label
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          data-rail-section=""
          aria-pressed={pressed}
          aria-label={label}
          tabIndex={pressed ? 0 : -1}
          onClick={() => onSelect(item.id)}
          className={cn(
            "relative grid size-8 place-items-center rounded-full text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            pressed && "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground",
          )}
        >
          <span className="[&_svg]:size-4">{item.icon}</span>
          {item.badge != null && item.badge !== "" ? (
            <span className="absolute end-0.5 top-0.5 size-1.5 rounded-full bg-destructive" aria-hidden />
          ) : null}
        </button>
      </TooltipTrigger>
      <TooltipContent side="right">{label}</TooltipContent>
    </Tooltip>
  )
}

function columnProps(props: RailSidebarProps, sectionId: string, onSectionChange: (id: string) => void, panelVisible: boolean, onTogglePanel?: () => void, showCollapse = true) {
  return {
    sections: props.sections,
    sectionId,
    onSectionChange,
    activeHref: props.activeHref,
    renderLink: props.renderLink,
    onNavigate: props.onNavigate,
    workspace: props.workspace,
    user: props.user,
    footerSlot: props.footerSlot,
    onSearch: props.onSearch,
    onOpenCommand: props.onOpenCommand,
    searchPlaceholder: props.searchPlaceholder,
    type: props.type,
    mark: props.mark,
    markLabel: props.markLabel,
    railClassName: props.railClassName,
