  prompt: string
  detail?: string
  options: readonly ClarifyOption[]
}

export type ClarificationImpact = {
  previous: number
  next: number
  delta: number
  reasons: ClarifyEffect[]
  priceLow: number
  priceHigh: number
  weeksLow: number
  weeksHigh: number
}

export type EstimateLine = {
  id: string
  phase: string
  hours: number
  rate: number
  historicalHours: number
}

export type EstimateTotals = {
  hours: number
  amount: number
  historicalHours: number
}

export type PriceLineKind = "base" | "upsell" | "downsell"

export type PriceLine = {
  id: string
  label: string
  amount: number
  kind: PriceLineKind
}

export type ProposalSection = {
  id: string
  title: string
  body: string
}

