  /** Formats a scrubbed point for the headline. Defaults to a grouped number. */
  formatValue?: (value: number, index: number) => string
  /** A quiet neutral fill under the line. */
  area?: boolean
  /** Pointer and keyboard scrubbing through the points. */
  interactive?: boolean
  className?: string
  classNames?: SparklineClassNames
}

export type SparklineClassNames = {
  root?: string
  caption?: string
  label?: string
  value?: string
  change?: string
  plot?: string
}

const toneClass = {
  accent: "text-primary",
  success: "text-[color:var(--chart-2)]",
  warning: "text-[color:var(--chart-4)]",
  danger: "text-destructive",
} as const

const rise: Variants = {
  hidden: (direction: number) => ({ opacity: 0, y: `${0.3 * direction}em`, filter: `blur(${motionPresets.blur.soft}px)` }),
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.standard, ease: [...motionPresets.ease.enter] } },
  gone: (direction: number) => ({ opacity: 0, y: `${-0.3 * direction}em`, filter: `blur(${motionPresets.blur.subtle}px)`, transition: { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } }),
}
const fade: Variants = {
  hidden: { opacity: 0, y: 0, filter: "blur(0px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
  gone: { opacity: 0, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
}
const amountIn = (text: string) => Number(text.replace(/,/g, "").replace(/−/g, "-").match(/-?\d+(?:\.\d+)?/)?.[0] ?? NaN)
const grouped = new Intl.NumberFormat("en-US")
const draw = { duration: motionPresets.duration.considered * 1.75, ease: [...motionPresets.ease.inOut] } as const
const quick = { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } as const

type Chunk = { slot: string; key: string; text: string }

function chunksOf(text: string, whole: boolean): Chunk[] {
  if (!text) return []
  if (whole) return [{ slot: "all", key: text, text }]
  if (!/\p{L}/u.test(text)) return [...text].map((char, index, all) => ({ slot: `n${all.length - index}`, key: char, text: char }))
  const words = text.split(/(?<=\s)/)
  return words.map((word, index) => ({ slot: `w${index}`, key: words.slice(0, index + 1).join(""), text: word }))
}

function Roll({ text, direction, whole = false, morph = false, className }: { text: string; direction?: number; whole?: boolean; morph?: boolean; className?: string }) {
  const reduceMotion = !!useReducedMotion()
  const sizer = useRef<HTMLSpanElement>(null)
  const width = useMotionValue<number | "auto">("auto")
  const [shown, setShown] = useState({ text, direction: 1 })
  if (shown.text !== text) setShown({ text, direction: direction ?? (amountIn(text) < amountIn(shown.text) ? -1 : 1) })
  useEffect(() => {
    const node = sizer.current
    if (!node || typeof ResizeObserver === "undefined") return
    let measured: string | null = null
    const observer = new ResizeObserver(([entry]) => {
      const next = entry.borderBoxSize?.[0]?.inlineSize ?? node.offsetWidth
      if (measured !== null && measured !== node.textContent && !reduceMotion) animate(width, next, motionPresets.spring.morph)
      else width.jump(next)
      measured = node.textContent
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [morph, reduceMotion, width])
  const numeric = !whole && !/\p{L}/u.test(text)
  const variants = reduceMotion ? fade : rise
  const anchor = numeric ? "right" : "left"
  return (
    <motion.span className={cn("relative inline-flex max-w-full overflow-x-clip align-top whitespace-pre", numeric && "justify-end", className)} style={morph ? { width } : undefined}>
      {morph ? <span ref={sizer} className="pointer-events-none absolute top-0 left-0 whitespace-pre invisible" aria-hidden="true">{text}</span> : null}
      <span className="relative inline-block whitespace-pre">
        <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
          {chunksOf(text, whole).map((chunk) => (
            <motion.span key={chunk.slot} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">
              <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
                <motion.span key={chunk.key} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">{chunk.text}</motion.span>
              </AnimatePresence>
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </motion.span>
  )
}

type Point = [number, number]
const inset = 5
const cap = 1.25
const grid = Array.from({ length: 161 }, (_, index) => index / 160)

function curveFor(data: number[]): Point[] {
  const min = Math.min(...data)
  const span = Math.max(...data) - min
  const ys = data.map((value) => (span ? (value - min) / span : 0.5))
  const last = ys.length - 1
  const step = 1 / last
  const slopes = ys.slice(1).map((y, index) => (y - ys[index]) / step)
  const tangents = ys.map((_, index) => (index === 0 || index === last ? slopes[0] : (Math.sign(slopes[index - 1]) + Math.sign(slopes[index])) * Math.min(Math.abs(slopes[index - 1]), Math.abs(slopes[index]), Math.abs(slopes[index - 1] + slopes[index]) / 4) || 0))
  if (last > 1) {
    tangents[0] = (3 * slopes[0] - tangents[1]) / 2
    tangents[last] = (3 * slopes[last - 1] - tangents[last - 1]) / 2
  }
  const samples = Math.max(1, Math.min(16, Math.round(128 / last)))
  const points: Point[] = []
  for (let index = 0; index < last; index++) {
    for (let sample = 0; sample < samples; sample++) {
      const t = sample / samples
      const t2 = t * t
      const t3 = t2 * t
      const y = (2 * t3 - 3 * t2 + 1) * ys[index] + (t3 - 2 * t2 + t) * step * tangents[index] + (3 * t2 - 2 * t3) * ys[index + 1] + (t3 - t2) * step * tangents[index + 1]
      points.push([(index + t) * step, Math.min(1, Math.max(0, y))])
    }
  }
  points.push([1, ys[last]])
  return points
}

function heightAt(shape: Point[], x: number) {
  let low = 0
  let high = shape.length - 1
  if (x <= shape[low][0]) return shape[low][1]
  if (x >= shape[high][0]) return shape[high][1]
  while (high - low > 1) {
    const middle = (low + high) >> 1
    if (shape[middle][0] < x) low = middle
    else high = middle
  }
  const [x0, y0] = shape[low]
  const [x1, y1] = shape[high]
  return x1 === x0 ? y1 : y0 + ((y1 - y0) * (x - x0)) / (x1 - x0)
}

function geometryOf(shape: Point[], w: number, h: number, at: number) {
  const toY = (y: number) => inset + (1 - y) * (h - inset * 2)
  const points = shape.map(([x, y]): Point => [x * w, toY(y)])
  const pairs = points.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`)
  const cx = at * w
  const cy = toY(heightAt(shape, at))
  return { points, line: pairs.join(" "), trail: `M${pairs.join("L")}`, fill: `M${pairs.join("L")}L${w},${h}L0,${h}Z`, dot: `${cx},${cy} ${cx},${cy}`, cx }
}

function tipAt(points: Point[], progress: number) {
  const steps = points.slice(1).map(([x, y], index) => Math.hypot(x - points[index][0], y - points[index][1]))
  let left = progress * steps.reduce((sum, step) => sum + step, 0)
  for (let index = 0; index < steps.length; index++) {
    if (left <= steps[index]) return points[index][0] + (points[index + 1][0] - points[index][0]) * (steps[index] ? left / steps[index] : 1)
    left -= steps[index]
  }
  return points[points.length - 1][0]
}

export function Sparkline({ data, label, value, change, tone = "accent", width = 160, height = 52, labels, formatValue, area = true, interactive = true, className, classNames }: SparklineProps) {
  const safeData = data.length > 1 ? data : [data[0] ?? 0, data[0] ?? 0]
  const last = safeData.length - 1
  const key = safeData.join(",")
  const target = useMemo(() => curveFor(key.split(",").map(Number)), [key])
  const description = `${label}: ${value ?? safeData[last]}. ${change ?? ""}`.trim()
  const uid = `sparkline${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const ref = useRef<HTMLElement>(null)
  const plot = useRef<HTMLDivElement>(null)
  const inView = useInView(ref, { once: true, amount: 0.5 })
  const reduceMotion = !!useReducedMotion()
  const [box, setBox] = useState({ w: width, h: height })
  const [active, setActive] = useState<number | null>(null)
  const [landed, setLanded] = useState(false)
  const index = active === null ? null : Math.min(active, last)
  const [moved, setMoved] = useState({ index, direction: 1 })
  if (moved.index !== index) setMoved({ index, direction: index === null || moved.index === null ? 1 : Math.sign(index - moved.index) || 1 })

  const [first] = useState(() => geometryOf(target, width, height, 1))
  const shape = useRef(target)
  const size = useRef(box)
  const drawn = useMotionValue(0)
  const cursor = useMotionValue(1)
  const line = useMotionValue(first.line)
  const trail = useMotionValue(first.trail)
  const fill = useMotionValue(first.fill)
  const dot = useMotionValue(first.dot)
  const cursorX = useMotionValue(first.cx)
  const lit = useMotionValue(first.cx + cap + 16)
  const dim = useMotionValue(first.cx + cap)
  const reveal = useMotionValue(0)
  const lineOpacity = useTransform(drawn, (progress) => (progress > 0.001 ? 1 : 0))
  const stroke = toneClass[tone]

  const paint = useCallback(() => {
    const { w, h } = size.current
    const progress = drawn.get()
    const next = geometryOf(shape.current, w, h, cursor.get())
    line.set(next.line)
    trail.set(next.trail)
    fill.set(next.fill)
    dot.set(next.dot)
    cursorX.set(next.cx)
    lit.set(next.cx + cap + 16)
    dim.set(next.cx + cap)
    reveal.set(progress >= 1 ? w + 32 : tipAt(next.points, progress) + 16)
  }, [cursor, cursorX, dim, dot, drawn, fill, line, lit, reveal, trail])
  useMotionValueEvent(cursor, "change", paint)
  useMotionValueEvent(drawn, "change", paint)

  useLayoutEffect(() => {
    const node = plot.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      const w = node.clientWidth
      if (w) setBox((current) => (Math.abs(current.w - w) < 0.5 ? current : { w, h: (w * height) / width }))
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [height, width])
  useLayoutEffect(() => {
    size.current = box
    paint()
  }, [box, paint])

  useEffect(() => {
    if (reduceMotion) {
      drawn.jump(1)
      const frame = requestAnimationFrame(() => setLanded(true))
      return () => cancelAnimationFrame(frame)
    }
    if (!inView) return
    const controls = animate(drawn, 1, { ...draw, onComplete: () => setLanded(true) })
    return () => controls.stop()
  }, [drawn, inView, reduceMotion])

  useEffect(() => {
    const from = shape.current
    if (from === target) return
    if (reduceMotion) {
      shape.current = target
      paint()
      return
    }
    const xs = [...new Set([...grid, ...target.map(([x]) => x)])].sort((a, b) => a - b)
    const start = xs.map((x) => heightAt(from, x))
    const goal = xs.map((x) => heightAt(target, x))
    const controls = animate(0, 1, {
      ...motionPresets.spring.smooth,
      onUpdate: (progress) => {
        shape.current = xs.map((x, at): Point => [x, start[at] + (goal[at] - start[at]) * progress])
        paint()
      },
      onComplete: () => {
        shape.current = target
        paint()
      },
    })
    return () => controls.stop()
  }, [paint, reduceMotion, target])

  useEffect(() => {
    const to = index === null ? 1 : index / last
    if (reduceMotion) {
      cursor.jump(to)
      return
    }
    const controls = animate(cursor, to, motionPresets.spring.snappy)
    return () => controls.stop()
  }, [cursor, index, last, reduceMotion])

  const scrubbing = index !== null
  const format = (at: number) => (formatValue ? formatValue(safeData[at], at) : grouped.format(safeData[at]))
  const point = format(index ?? last)
  const when = labels?.[index ?? last]
  const headline = value === undefined ? undefined : scrubbing ? point : value
  const aside = index === null ? change ?? "" : value === undefined ? [point, when].filter(Boolean).join(" · ") : when ?? `${index + 1} of ${last + 1}`
  const pointAt = (clientX: number) => {
    const rect = plot.current?.getBoundingClientRect()
    return rect?.width ? Math.max(0, Math.min(last, Math.round(((clientX - rect.left) / rect.width) * last))) : last
  }
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape" && scrubbing) {
      event.preventDefault()
      setActive(null)
      return
    }
    const from = index ?? last
    const page = Math.max(1, Math.round((last + 1) / 6))
    const next = ({ ArrowLeft: from - 1, ArrowDown: from - 1, ArrowRight: from + 1, ArrowUp: from + 1, PageDown: from - page, PageUp: from + page, Home: 0, End: last } as Record<string, number>)[event.key]
    if (next === undefined) return
    event.preventDefault()
    setActive(Math.max(0, Math.min(last, next)))
  }
  const scrub = interactive
    ? {
        role: "slider" as const,
        tabIndex: 0,
        "aria-label": `${label}, explore values`,
        "aria-valuemin": 1,
        "aria-valuemax": last + 1,
        "aria-valuenow": (index ?? last) + 1,
        "aria-valuetext": `${when ?? (index === null ? "Latest" : `Point ${index + 1} of ${last + 1}`)}: ${point}`,
        onPointerDown: (event: PointerEvent<HTMLDivElement>) => setActive(pointAt(event.clientX)),
        onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType === "mouse" || event.buttons) setActive(pointAt(event.clientX))
        },
        onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType !== "mouse") setActive(null)
        },
        onPointerLeave: () => setActive(null),
        onPointerCancel: () => setActive(null),
        onBlur: () => setActive(null),
        onKeyDown,
      }
    : {}

  return (
    <figure ref={ref} data-slot="sparkline" aria-label={description} className={cn("grid min-w-0 gap-3 text-foreground", className, classNames?.root)}>
      <figcaption data-slot="sparkline-caption" className={cn("flex min-w-0 items-baseline gap-2 text-sm text-muted-foreground", classNames?.caption)}>
        <span data-slot="sparkline-label" className={cn("min-w-0 overflow-hidden whitespace-nowrap", classNames?.label)}>
          <Roll text={label} whole />
        </span>
        {headline !== undefined ? (
          <strong data-slot="sparkline-value" className={cn("ml-auto text-lg font-medium text-foreground tabular-nums", classNames?.value)}>
            <Roll text={headline} morph />
          </strong>
        ) : null}
        <small data-slot="sparkline-change" className={cn("shrink-0 text-xs font-medium tabular-nums transition-colors", stroke, scrubbing && "text-muted-foreground", classNames?.change)}>
          <Roll text={aside} direction={scrubbing ? moved.direction : undefined} morph />
        </small>
      </figcaption>
      <div
        ref={plot}
        data-slot="sparkline-plot"
        data-interactive={interactive || undefined}
        className={cn("relative min-w-0 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-offset-8", interactive && "cursor-default touch-pan-y select-none", classNames?.plot)}
        {...scrub}
      >
        <svg data-slot="sparkline-chart" className="block h-auto w-full overflow-visible" viewBox={`0 0 ${box.w} ${box.h}`} aria-hidden="true" focusable="false">
          <defs>
            <clipPath id={`${uid}-lit`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={lit} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-dim`} clipPathUnits="userSpaceOnUse"><motion.rect x={dim} y={-16} width={box.w + 32} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-fill`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={reveal} height={box.h + 32} /></clipPath>
          </defs>
          {area ? <motion.path className={cn("fill-current stroke-none opacity-10", stroke)} d={fill} clipPath={`url(#${uid}-fill)`} /> : null}
          <line className="stroke-border" strokeWidth={1} x1="0" y1={box.h - 0.5} x2={box.w} y2={box.h - 0.5} />
          <motion.path className="fill-none stroke-border stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]" d={trail} clipPath={`url(#${uid}-dim)`} initial={false} animate={{ opacity: scrubbing && landed ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]", stroke)} points={line} clipPath={`url(#${uid}-lit)`} style={{ pathLength: drawn, opacity: lineOpacity }} />
          <motion.line className="stroke-border" strokeWidth={1} x1={cursorX} x2={cursorX} y1={0} y2={box.h} initial={false} animate={{ opacity: scrubbing ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current", stroke)} points={dot} initial={false} animate={{ opacity: landed ? 1 : 0, strokeWidth: landed ? (scrubbing ? 10 : 7) : 0 }} transition={reduceMotion ? { duration: 0 } : { opacity: quick, strokeWidth: motionPresets.spring.snappy }} strokeLinecap="round" />
        </svg>
      </div>
    </figure>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type TrendPoint = { x: number | string; y: number }

export type TrendSeries = {
  id: string
  label: string
  points: readonly TrendPoint[]
  emphasis?: "primary" | "muted"
}

export type TrendBand = {
  from: number | string
  to: number | string
  label: string
  tone?: "highlight" | "secondary"
}

export type TrendMarker = { x: number | string; label: string }

export type AnnotatedTrendChartClassNames = {
  root?: string
  plot?: string
  tooltip?: string
  table?: string
}

export type AnnotatedTrendChartProps = {
  series: readonly TrendSeries[]
  /** Accessible name. A summary is appended from the primary series. */
  label: string
  target?: { y: number; label: string }
  bands?: readonly TrendBand[]
  markers?: readonly TrendMarker[]
  endLabel?: boolean
  yFormat?: DashboardFormat
  locale?: string
  currency?: string
  area?: boolean
  /** When false, muted series stay hidden. */
  compare?: boolean
  height?: number
  className?: string
  classNames?: AnnotatedTrendChartClassNames
}

function keyOf(value: number | string) {
  return String(value)
}

function smoothPath(points: { x: number; y: number }[]) {
  if (!points.length) return ""
  if (points.length === 1) return `M ${points[0].x} ${points[0].y}`
  let path = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`
  for (let index = 0; index < points.length - 1; index += 1) {
    const p0 = points[index - 1] ?? points[index]
    const p1 = points[index]
    const p2 = points[index + 1]
    const p3 = points[index + 2] ?? p2
    const c1x = p1.x + (p2.x - p0.x) / 6
    const c1y = p1.y + (p2.y - p0.y) / 6
    const c2x = p2.x - (p3.x - p1.x) / 6
    const c2y = p2.y - (p3.y - p1.y) / 6
    path += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`
  }
  return path
}

function buildSummary(label: string, primary: TrendSeries | undefined, format: (value: number) => string, target?: { y: number; label: string }) {
  if (!primary?.points.length) return label
  const first = primary.points[0]
  const last = primary.points[primary.points.length - 1]
  const direction = last.y === first.y ? "held" : last.y > first.y ? "rose" : "fell"
  const targetText = target ? `; ${target.label}` : ""
  return `${label}: ${primary.label} ${direction} from ${format(first.y)} to ${format(last.y)} over ${primary.points.length} points${targetText}`
}

export function AnnotatedTrendChart({
  series,
  label,
  target,
  bands = [],
  markers = [],
  endLabel = true,
  yFormat = "number",
  locale = "en-US",
  currency = "USD",
  area = true,
  compare = true,
  height = 220,
  className,
  classNames,
}: AnnotatedTrendChartProps) {
  const format = React.useCallback(
    (value: number) => formatDashboardValue(value, yFormat, locale, currency),
    [currency, locale, yFormat],
  )
  const visible = series.filter((line) => compare || line.emphasis !== "muted")
  const keys: string[] = []
  for (const line of visible) {
    for (const point of line.points) {
      const key = keyOf(point.x)
      if (!keys.includes(key)) keys.push(key)
    }
  }
  const [width, setWidth] = React.useState(640)
  const [index, setIndex] = React.useState<number | null>(null)
  const [tableOpen, setTableOpen] = React.useState(false)
  const plotRef = React.useRef<HTMLDivElement>(null)
  const gradientId = React.useId().replace(/:/g, "")

  React.useEffect(() => {
    const node = plotRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      const next = entries[0]?.contentRect.width
      if (next && next > 0) setWidth(next)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  const compact = width < 360
  const pad = { left: 40, right: compact || !endLabel ? 12 : 72, top: 28, bottom: 28 }
  const innerW = Math.max(1, width - pad.left - pad.right)
  const innerH = Math.max(1, height - pad.top - pad.bottom)
  const values = visible.flatMap((line) => line.points.map((point) => point.y))
  if (target) values.push(target.y)
  const min = values.length ? Math.min(...values) : 0
  const max = values.length ? Math.max(...values) : 1
  const span = max - min || 1
  const yAt = (value: number) => pad.top + innerH - ((value - min) / span) * innerH
  const xAt = (key: string) => {
    const at = Math.max(0, keys.indexOf(key))
    const step = keys.length <= 1 ? 0 : at / (keys.length - 1)
    return pad.left + step * innerW
  }
  const primary = visible.find((line) => line.emphasis !== "muted") ?? visible[0]
  const summary = buildSummary(label, primary, format, target)
  const ticks = 4
  const yTicks = Array.from({ length: ticks }, (_, step) => min + (span * step) / (ticks - 1))
  const xTickCount = compact ? 2 : Math.min(4, keys.length)
  const xTicks = Array.from({ length: xTickCount }, (_, step) => keys[Math.round((step * (keys.length - 1)) / Math.max(1, xTickCount - 1))] ?? keys[0])

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!keys.length) return
    const last = keys.length - 1
    if (event.key === "Escape") {
      setIndex(null)
      return
    }
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return
    event.preventDefault()
    setIndex((current) => {
      if (current == null) {
        if (event.key === "End" || event.key === "ArrowLeft") return last
        return 0
      }
      if (event.key === "Home") return 0
      if (event.key === "End") return last
      if (event.key === "ArrowRight") return Math.min(last, current + 1)
      return Math.max(0, current - 1)
    })
  }

  const activeKey = index != null ? keys[index] : null

  return (
    <div data-slot="annotated-trend-chart" className={cn("min-w-0", className, classNames?.root)}>
      <div ref={plotRef} className={cn("relative min-w-0", classNames?.plot)}>
        <div
          role="img"
          tabIndex={0}
          aria-label={summary}
          onKeyDown={onKeyDown}
          className="outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
        >
          <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} className="block text-foreground" aria-hidden>
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="var(--chart-3)" stopOpacity="0.35" />
                <stop offset="1" stopColor="var(--chart-3)" stopOpacity="0" />
              </linearGradient>
            </defs>
            {yTicks.map((tick) => (
              <g key={tick}>
                <line x1={pad.left} x2={width - pad.right} y1={yAt(tick)} y2={yAt(tick)} className="stroke-border" strokeDasharray="2 4" />
                <text x={pad.left - 6} y={yAt(tick) + 3} textAnchor="end" className="fill-muted-foreground text-[10px]">
                  {format(tick)}
                </text>
              </g>
            ))}
            {bands.map((band) => {
              const x1 = xAt(keyOf(band.from))
              const x2 = xAt(keyOf(band.to))
              const left = Math.min(x1, x2)
              return (
                <g key={band.label}>
                  <rect
                    x={left}
                    y={pad.top}
                    width={Math.max(2, Math.abs(x2 - x1))}
                    height={innerH}
                    className={band.tone === "secondary" ? "fill-chart-3" : "fill-chart-2"}
                    fillOpacity={0.25}
                  />
                  <text x={left + 4} y={pad.top + 12} className="fill-foreground text-[10px]">
                    {band.label}
                  </text>
                </g>
              )
            })}
            {target ? (
              <g>
                <line
                  x1={pad.left}
                  x2={width - pad.right}
                  y1={yAt(target.y)}
                  y2={yAt(target.y)}
                  className="stroke-destructive"
                  strokeDasharray="4 4"
                />
                <text x={width - pad.right} y={Math.max(12, yAt(target.y) - 6)} textAnchor="end" className="fill-destructive text-[10px]">
                  {target.label}
                </text>
              </g>
            ) : null}
            {visible.map((line) => {
              const points = line.points.map((point) => ({ x: xAt(keyOf(point.x)), y: yAt(point.y) }))
              const d = smoothPath(points)
              const muted = line.emphasis === "muted"
              const last = points[points.length - 1]
              const areaPath = points.length
                ? `${d} L ${points[points.length - 1].x.toFixed(2)} ${(pad.top + innerH).toFixed(2)} L ${points[0].x.toFixed(2)} ${(pad.top + innerH).toFixed(2)} Z`
                : ""
              return (
                <g key={line.id}>
                  {area && !muted && areaPath ? <path d={areaPath} fill={`url(#${gradientId})`} /> : null}
                  <path
                    d={d}
                    fill="none"
                    className={muted ? "stroke-chart-3" : "stroke-primary"}
                    strokeWidth={muted ? 1.5 : 2}
                    strokeOpacity={muted ? 0.7 : 1}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                  />
                  {endLabel && !compact && muted && last ? (
                    <text x={last.x + 6} y={last.y + 4} className="fill-muted-foreground text-[10px]">
                      {line.label}
                    </text>
                  ) : null}
                </g>
              )
            })}
            {primary && primary.points.length ? (
              <g>
                {(() => {
                  const last = primary.points[primary.points.length - 1]
                  const x = xAt(keyOf(last.x))
                  const y = yAt(last.y)
                  return (
                    <>
                      <circle cx={x} cy={y} r="5" className="fill-chart-2 stroke-primary" strokeWidth="2" />
                      <rect x={x - 22} y={y - 26} width="44" height="16" rx="8" className="fill-primary" />
                      <text x={x} y={y - 15} textAnchor="middle" className="fill-primary-foreground text-[10px]">
                        {format(last.y)}
                      </text>
                    </>
                  )
                })()}
              </g>
            ) : null}
            {activeKey ? (
              <line x1={xAt(activeKey)} x2={xAt(activeKey)} y1={pad.top} y2={pad.top + innerH} className="stroke-foreground" strokeDasharray="2 3" />
            ) : null}
            {xTicks.filter(Boolean).map((key) => (
              <text key={key} x={xAt(key)} y={height - 8} textAnchor="middle" className="fill-muted-foreground text-[10px]">
                {key}
              </text>
            ))}
            {markers.map((marker) => (
              <text key={marker.label} x={xAt(keyOf(marker.x))} y={pad.top - 8} textAnchor="middle" className="fill-foreground text-[10px]">
                {marker.label}
              </text>
            ))}
          </svg>
        </div>
        {activeKey ? (
          <div
            data-slot="annotated-trend-tooltip"
            className={cn("mt-2 rounded-lg bg-popover px-3 py-2 text-xs text-popover-foreground shadow-sm ring-1 ring-foreground/10", classNames?.tooltip)}
          >
            <p className="font-medium">{activeKey}</p>
            <ul>
              {visible.map((line) => {
                const point = line.points.find((item) => keyOf(item.x) === activeKey)
                if (!point) return null
                return (
                  <li key={line.id}>
                    {line.label}: {format(point.y)}
                  </li>
                )
              })}
            </ul>
          </div>
        ) : null}
      </div>
      {compact && endLabel ? (
        <ul className="mt-2 flex flex-wrap gap-3 text-xs text-muted-foreground">
          {visible.map((line) => (
            <li key={line.id} className="inline-flex items-center gap-1">
              <span className={cn("h-0.5 w-4", line.emphasis === "muted" ? "bg-chart-3" : "bg-primary")} aria-hidden />
              {line.label}
            </li>
          ))}
        </ul>
      ) : null}
      <Button type="button" variant="ghost" size="sm" className="mt-2" aria-expanded={tableOpen} onClick={() => setTableOpen((open) => !open)}>
        {tableOpen ? "Hide data" : "View data"}
      </Button>
      <table className={cn("text-left text-sm", tableOpen ? "mt-2 w-full" : "sr-only", classNames?.table)}>
        <caption className="sr-only">{summary}</caption>
        <thead>
          <tr>
            <th scope="col">Point</th>
            {visible.map((line) => (
              <th key={line.id} scope="col">
                {line.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {keys.map((key) => (
            <tr key={key}>
              <th scope="row">{key}</th>
              {visible.map((line) => {
                const point = line.points.find((item) => keyOf(item.x) === key)
                return <td key={line.id}>{point ? format(point.y) : "—"}</td>
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { clampRatio, formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type RadialGaugeTone = "primary" | "neutral" | "destructive"

export type RadialGaugeClassNames = {
  root?: string
  value?: string
  label?: string
  over?: string
  ticks?: string
}

export type RadialGaugeProps = {
  value: number
  min?: number
  max?: number
  /** Accessible name for the meter. */
  label: string
  ticks?: number
  format?: DashboardFormat
  formatter?: (value: number) => string
  locale?: string
  currency?: string
  overLabel?: string
  tone?: RadialGaugeTone
  /** arc keeps the needle. ticks is a needle-less semicircle of marks. */
  variant?: "arc" | "ticks"
  /** Shown after the value on the ticks variant, for example "%". */
  suffix?: string
  className?: string
  classNames?: RadialGaugeClassNames
}

const CX = 100
const CY = 96
const RADIUS = 74

function point(angle: number, radius: number) {
  return {
    x: CX + Math.cos(angle) * radius,
    y: CY - Math.sin(angle) * radius,
  }
}

function arcPath(radius: number) {
  const start = point(Math.PI, radius)
  const end = point(0, radius)
  return `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} A ${radius} ${radius} 0 0 1 ${end.x.toFixed(2)} ${end.y.toFixed(2)}`
}

const toneClass: Record<RadialGaugeTone, string> = {
  primary: "stroke-primary text-primary",
  neutral: "stroke-muted-foreground text-muted-foreground",
  destructive: "stroke-destructive text-destructive",
}

export function RadialGauge({
  value,
  min = 0,
  max = 100,
  label,
  ticks = 5,
  format = "number",
  formatter,
  locale = "en-US",
  currency = "USD",
  overLabel = "Over budget",
  tone = "primary",
  variant = "arc",
  suffix,
  className,
  classNames,
}: RadialGaugeProps) {
  const safeMax = max > min ? max : min + 1
  const over = value > max
  const ratio = clampRatio(value, min, safeMax)
  const clamped = value < min || value > max
  const angle = Math.PI * (1 - ratio)
  const needle = point(angle, RADIUS - 10)
  const hub = point(angle, 8)
  const text = formatter ? formatter(value) : formatDashboardValue(value, format, locale, currency)
  const tickCount = variant === "ticks" ? Math.max(12, Math.min(48, Math.round(ticks))) : Math.max(2, Math.min(9, Math.round(ticks)))
  const marks = Array.from({ length: tickCount }, (_, index) => {
    const at = Math.PI * (1 - index / (tickCount - 1))
    const outer = point(at, RADIUS + 2)
    const inner = point(at, RADIUS - 8)
    return { outer, inner, key: index }
  })
  const valuetext = over ? `${text}, ${overLabel}` : text
  const filledTicks = Math.round(ratio * tickCount)

  if (variant === "ticks") {
    return (
      <div
        data-slot="radial-gauge"
        data-variant="ticks"
        data-state={over ? "over" : "ok"}
        data-tone={over ? "destructive" : tone}
        role="meter"
        aria-label={label}
        aria-valuenow={value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={valuetext}
        className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
      >
        <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
          <g className={classNames?.ticks}>
            {marks.map((mark) => (
              <line
                key={mark.key}
                x1={mark.inner.x}
                y1={mark.inner.y}
                x2={mark.outer.x}
                y2={mark.outer.y}
                className={mark.key < filledTicks ? "stroke-foreground" : "stroke-muted-foreground/30"}
                strokeWidth="2.5"
                strokeLinecap="round"
              />
            ))}
          </g>
        </svg>
        <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>
          {text}
          {suffix ? <span className="align-super text-sm">{suffix}</span> : null}
        </p>
        <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      </div>
    )
  }

  return (
    <div
      data-slot="radial-gauge"
      data-state={over ? "over" : "ok"}
      data-tone={over ? "destructive" : tone}
      role="meter"
      aria-label={label}
      aria-valuenow={value}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={valuetext}
      className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
    >
      <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
        <path d={arcPath(RADIUS)} className="fill-none stroke-muted" strokeWidth="8" strokeLinecap="round" />
        <path
          d={arcPath(RADIUS)}
          pathLength={100}
          className={cn("fill-none", over ? "stroke-destructive" : toneClass[tone])}
          strokeWidth="8"
          strokeLinecap="round"
          strokeDasharray={`${ratio * 100} 100`}
        />
        <g className={classNames?.ticks}>
          {marks.map((mark) => (
            <line
              key={mark.key}
              x1={mark.inner.x}
              y1={mark.inner.y}
              x2={mark.outer.x}
              y2={mark.outer.y}
              className="stroke-muted-foreground"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          ))}
        </g>
        <line
          data-slot="radial-gauge-needle"
          data-clamped={clamped ? "true" : "false"}
          x1={hub.x}
          y1={hub.y}
          x2={needle.x}
          y2={needle.y}
          className={over ? "stroke-destructive" : "stroke-foreground"}
          strokeWidth="2.5"
          strokeLinecap="round"
        />
        <circle cx={CX} cy={CY} r="4" className={over ? "fill-destructive" : "fill-foreground"} />
      </svg>
      <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>{text}</p>
      <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      {over ? <p className={cn("text-xs font-medium text-destructive", classNames?.over)}>{overLabel}</p> : null}
    </div>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import { createContext, useCallback, useContext, useEffect, useId, useMemo, useRef, useState, useSyncExternalStore } from "react"
import type { CSSProperties, KeyboardEvent, ReactNode } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import type { Transition } from "motion/react"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export interface TimelineEvent {
  id: string
  /** When it happened, as an ISO string or epoch milliseconds. */
  at: string | number
  /** Who did it, shown first in the foreground color. */
  actor?: string
  /** What happened, completing the actor: "merged Checkout redesign into main". */
  title: string
  /** Short context under the title, such as a pull request or a build. */
  meta?: string
  /** Revealed in place when the row is expanded. Rows without detail are not interactive. */
  detail?: ReactNode
  /** Portrait for an event by a person. */
  avatar?: string
  /** Icon for a system event, used when there is no avatar. */
  icon?: ReactNode
  /** Status of a system event. Always say the outcome in the title too, so it never rests on color. */
  tone?: "neutral" | "success" | "danger"
}

/**
 * A vertical activity feed grouped by day, for project history, audit logs, and deploy streams. Use it when order and
 * recency matter; use a table when people need to sort or compare. Day labels stay pinned while their updates scroll,
 * the connecting line draws itself as rows come into view, rows expand in place, and new updates slide in at the top
 * while the rest glide down. Arrow keys move between rows, Enter or Space expands one.
 */
export interface TimelineProps {
  /** Updates in any order; the newest shows first. */
  events: TimelineEvent[]
  /** Reference time for relative labels and day groups, in epoch milliseconds. Pass a ticking clock to keep labels fresh. */
  now: number
  /** Accessible name for the feed. */
  label: string
  /** Time zone for day groups and clock times. Fixed by default so server and client agree. */
  timeZone?: string
  locale?: string
  /** Height of the scrolling area. Without it the feed grows with the page and reveals on page scroll. */
  maxHeight?: number | string
  /** Scroll back to the top when a new update arrives while the feed is scrolled down. */
  scrollToNew?: boolean
  defaultExpanded?: string[]
  /** Heading level for the day labels. */
  headingLevel?: 2 | 3 | 4 | 5 | 6
  className?: string
  classNames?: TimelineClassNames
}

export type TimelineClassNames = {
  root?: string
  scroller?: string
  day?: string
  item?: string
  title?: string
  detail?: string
}

type Row = TimelineEvent & { time: number; day: string }
type Group = { day: string; label: string; rows: Row[] }

const HOUR = 3_600_000
const enter = [...motionPresets.ease.enter] as [number, number, number, number]
const standard = [...motionPresets.ease.standard] as [number, number, number, number]
const STEP = 0.09
const noopSubscribe = () => () => {}

function useReducedMotionSafe() {
  const hydrated = useSyncExternalStore(noopSubscribe, () => true, () => false)
  const reduced = useReducedMotion()
  return hydrated && !!reduced
}

type Clock = { schedule: () => number; reduced: boolean; fresh: Set<string> }
const RevealClock = createContext<Clock | null>(null)

function RiseText({ text, reduced, direction = 1 }: { text: string; reduced: boolean; direction?: number }) {
  return (
    <span className="relative inline-flex" aria-hidden="true">
      <AnimatePresence mode="popLayout" initial={false} custom={direction}>
        <motion.span
          key={text}
          className="inline-block whitespace-nowrap"
          custom={direction}
          variants={{
            from: (dir: number) => (reduced ? { opacity: 0 } : { opacity: 0, y: `${0.3 * dir}em`, filter: `blur(${motionPresets.blur.soft}px)` }),
            to: { opacity: 1, y: "0em", filter: "blur(0px)" },
            gone: (dir: number) => (reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: `${-0.3 * dir}em`, filter: `blur(${motionPresets.blur.subtle}px)`, transition: { duration: 0.14, ease: standard } }),
          }}
          initial="from"
          animate="to"
          exit="gone"
          transition={{ duration: reduced ? 0.15 : 0.22, ease: enter }}
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  )
}

function RollingCount({ value, reduced }: { value: number; reduced: boolean }) {
  const [state, setState] = useState({ value, direction: 1 })
  if (state.value !== value) setState({ value, direction: value > state.value ? 1 : -1 })
  const chars = [...String(value)]
  return (
    <span className="inline-flex" aria-hidden="true">
      {chars.map((char, index) => (
        <span key={chars.length - index} className="relative inline-flex overflow-clip">
          <RiseText text={char} reduced={reduced} direction={state.direction} />
        </span>
      ))}
    </span>
  )
}

function dayKey(time: number, timeZone: string) {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(time))
  const get = (type: string) => parts.find((part) => part.type === type)?.value ?? ""
  return `${get("year")}-${get("month")}-${get("day")}`
}

function relative(time: number, now: number) {
  const minutes = Math.max(0, Math.floor((now - time) / 60_000))
  if (minutes < 1) return { short: "Now", long: "just now" }
  if (minutes < 60) return { short: `${minutes}m`, long: `${minutes} ${minutes === 1 ? "minute" : "minutes"} ago` }
  const hours = Math.floor(minutes / 60)
  return { short: `${hours}h`, long: `${hours} ${hours === 1 ? "hour" : "hours"} ago` }
}

function DaySection({ id, fresh, reduced, children }: { id: string; fresh: boolean; reduced: boolean; children: ReactNode }) {
  const [entering, setEntering] = useState(fresh)
  return (
    <motion.section
      className="relative data-[entering]:overflow-clip"
      aria-labelledby={id}
      data-entering={entering || undefined}
      initial={fresh ? { height: 0, opacity: 0 } : false}
      animate={{ height: "auto", opacity: 1 }}
      exit={{ height: 0, opacity: 0, transition: { duration: reduced ? 0.1 : 0.2, ease: standard } }}
      transition={reduced ? { duration: 0.15 } : { height: motionPresets.spring.smooth, opacity: { duration: motionPresets.duration.standard, ease: enter } }}
      onAnimationComplete={() => setEntering(false)}
    >
      {children}
    </motion.section>
  )
}

const toneClass = {
  neutral: "bg-muted text-muted-foreground",
  success: "bg-primary/15 text-primary",
  danger: "bg-destructive/15 text-destructive",
}

function TimelineRow({ row, last, expanded, onToggle, timeLabel, timeFull, classNames }: { row: Row; last: boolean; expanded: boolean; onToggle: () => void; timeLabel: string; timeFull: string; classNames?: TimelineClassNames }) {
  const clock = useContext(RevealClock)!
  const { reduced } = clock
  const detailId = useId()
  const [revealDelay, setRevealDelay] = useState<number | null>(null)
  const fresh = clock.fresh.has(row.id)
  const [entering, setEntering] = useState(fresh)
  const shown = revealDelay !== null
  const delay = (revealDelay ?? 0) + (fresh ? 0.12 : 0)
  const pop: Transition = reduced ? { duration: 0, opacity: { duration: 0.15 } } : { ...motionPresets.spring.morph, visualDuration: 0.36, bounce: 0.32, delay, opacity: { duration: motionPresets.duration.fast, ease: enter, delay } }
  const draw: Transition = reduced ? { duration: 0 } : { ...motionPresets.spring.smooth, visualDuration: 0.34, delay: delay + 0.1 }
  const tone = row.avatar ? undefined : row.tone ?? "neutral"
  const Trigger = row.detail ? "button" : "div"

  return (
    <motion.li
      data-slot="timeline-item"
      className={cn("relative pl-10 data-[entering]:overflow-clip", classNames?.item)}
      data-entering={entering || undefined}
      initial={fresh ? { height: 0 } : false}
      animate={{ height: "auto" }}
      exit={{ height: 0, opacity: 0, transition: reduced ? { duration: 0.1 } : { height: { ...motionPresets.spring.smooth, visualDuration: 0.3 }, opacity: { duration: 0.12 } } }}
      transition={reduced ? { duration: 0 } : motionPresets.spring.smooth}
      onAnimationComplete={() => setEntering(false)}
      onViewportEnter={() => setRevealDelay((current) => current ?? clock.schedule())}
      viewport={{ once: true, amount: 0.2 }}
    >
      <motion.span
        data-slot="timeline-marker"
        data-tone={tone}
        aria-hidden="true"
        className={cn("absolute top-2 left-0 z-10 grid size-7 place-items-center rounded-full text-muted-foreground ring-1 ring-foreground/10 [&_img]:size-full [&_img]:rounded-[inherit] [&_img]:object-cover [&_svg]:size-3.5", tone && toneClass[tone])}
        initial={{ scale: 0.4, opacity: 0 }}
        animate={shown ? { scale: 1, opacity: 1 } : undefined}
        transition={pop}
      >
        {row.avatar ? (
          // Registry pieces stay free of the Next image runtime.
          // eslint-disable-next-line @next/next/no-img-element
          <img src={row.avatar} alt="" width={28} height={28} decoding="async" />
        ) : row.icon}
      </motion.span>
      {!last ? <motion.span className="absolute top-10 bottom-0 left-[13px] w-px origin-top bg-border" aria-hidden="true" initial={{ scaleY: 0 }} animate={shown ? { scaleY: 1 } : undefined} transition={draw} /> : null}
      <motion.div
        className="min-w-0"
        initial={fresh ? (reduced ? { opacity: 0 } : { opacity: 0, y: -10, filter: `blur(${motionPresets.blur.soft}px)` }) : false}
        animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
        transition={reduced ? { duration: 0.15 } : { y: motionPresets.spring.smooth, opacity: { duration: motionPresets.duration.standard, ease: enter, delay: 0.05 }, filter: { duration: motionPresets.duration.standard, ease: enter, delay: 0.05 } }}
      >
        <Trigger
          className={cn("m-0 grid w-full grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 rounded-lg bg-transparent p-3 text-left text-inherit max-[420px]:gap-x-2 max-[420px]:px-2", row.detail && "grid-cols-[minmax(0,1fr)_auto_1rem] cursor-pointer hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none")}
          {...(row.detail ? { type: "button" as const, "data-timeline-trigger": "", "aria-expanded": expanded, "aria-controls": expanded ? detailId : undefined, onClick: onToggle } : {})}
        >
          <span className="grid min-w-0 gap-0.5">
            <span data-slot="timeline-title" className={cn("text-sm leading-5 text-muted-foreground", classNames?.title)}>
              {row.actor ? <span className="font-medium text-foreground">{row.actor}</span> : null}
              {row.actor ? " " : ""}
              {row.title}
            </span>
            {row.meta ? <span className="text-xs leading-snug text-muted-foreground">{row.meta}</span> : null}
          </span>
          <time className="flex min-w-11 justify-end text-xs leading-5 whitespace-nowrap text-muted-foreground tabular-nums" dateTime={new Date(row.time).toISOString()} title={timeFull}>
            <RiseText text={timeLabel} reduced={reduced} />
            <span className="sr-only">{timeFull}</span>
          </time>
          {row.detail ? (
            <motion.span className="grid h-5 place-items-center text-muted-foreground" aria-hidden="true" initial={false} animate={{ rotate: expanded ? 180 : 0 }} transition={reduced ? { duration: 0 } : motionPresets.spring.snappy}>
              <ChevronDown size={16} strokeWidth={1.75} />
            </motion.span>
          ) : null}
        </Trigger>
        <AnimatePresence initial={false}>
          {expanded && row.detail ? (
            <motion.div
              key="detail"
              id={detailId}
              data-slot="timeline-detail"
              className={cn("overflow-clip", classNames?.detail)}
              initial={{ height: 0 }}
              animate={{ height: "auto" }}
              exit={{ height: 0, transition: reduced ? { duration: 0 } : { ...motionPresets.spring.smooth, visualDuration: 0.28 } }}
              transition={reduced ? { duration: 0 } : motionPresets.spring.smooth}
            >
              <motion.div
                className="px-3 pb-4 text-sm leading-snug text-muted-foreground max-[420px]:px-2"
                initial={reduced ? { opacity: 0 } : { opacity: 0, y: -4, filter: `blur(${motionPresets.blur.soft}px)` }}
                animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                exit={{ opacity: 0, transition: { duration: 0.1, ease: standard } }}
                transition={reduced ? { duration: 0.15 } : { duration: motionPresets.duration.standard, ease: enter, delay: 0.06 }}
              >
                {row.detail}
              </motion.div>
            </motion.div>
          ) : null}
        </AnimatePresence>
      </motion.div>
    </motion.li>
  )
}

export function Timeline({ events, now, label, timeZone = "UTC", locale = "en-US", maxHeight, scrollToNew = true, defaultExpanded = [], headingLevel = 3, className, classNames }: TimelineProps) {
  const reduced = useReducedMotionSafe()
  const id = useId()
  const scrollerRef = useRef<HTMLDivElement>(null)
  const [expanded, setExpanded] = useState(() => new Set(defaultExpanded))
  const ids = events.map((event) => event.id).join("|")
  const [known, setKnown] = useState(() => ({ ids, set: new Set(events.map((event) => event.id)), fresh: new Set<string>(), announcement: "" }))
  if (known.ids !== ids) {
    const added = events.filter((event) => !known.set.has(event.id))
    setKnown({
      ids,
      set: new Set(events.map((event) => event.id)),
      fresh: new Set([...known.fresh, ...added.map((event) => event.id)]),
      announcement: added.length ? `New update: ${added.map((event) => [event.actor, event.title].filter(Boolean).join(" ")).join(". ")}` : known.announcement,
    })
  }
  const trackRef = useRef<HTMLDivElement>(null)
  const scrolls = maxHeight !== undefined
  const [more, setMore] = useState(false)
  useEffect(() => {
    const scroller = scrollerRef.current
    const track = trackRef.current
    if (!scrolls || !scroller || !track || typeof ResizeObserver === "undefined") return
    const update = () => setMore(scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop > 2)
    update()
    scroller.addEventListener("scroll", update, { passive: true })
    const observer = new ResizeObserver(update)
    observer.observe(scroller)
    observer.observe(track)
    return () => {
      scroller.removeEventListener("scroll", update)
      observer.disconnect()
    }
  }, [scrolls])

  const newestId = events.reduce<TimelineEvent | null>((latest, event) => (!latest || new Date(event.at).getTime() > new Date(latest.at).getTime() ? event : latest), null)?.id
  useEffect(() => {
    const scroller = scrollerRef.current
    if (!scrollToNew || !scroller || scroller.scrollTop < 1) return
    scroller.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" })
  }, [newestId, scrollToNew, reduced])

  const [initialDays] = useState(() => new Set(events.map((event) => dayKey(new Date(event.at).getTime(), timeZone))))
  const groups = useMemo<Group[]>(() => {
    const today = dayKey(now, timeZone)
    const yesterday = dayKey(now - 24 * HOUR, timeZone)
    const heading = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric", timeZone })
    const byDay = new Map<string, Row[]>()
    ;[...events]
      .map((event) => ({ ...event, time: new Date(event.at).getTime() }))
      .sort((a, b) => b.time - a.time)
      .forEach((event) => {
        const day = dayKey(event.time, timeZone)
        byDay.set(day, [...(byDay.get(day) ?? []), { ...event, day }])
      })
    return [...byDay].map(([day, rows]) => ({ day, rows, label: day === today ? "Today" : day === yesterday ? "Yesterday" : heading.format(new Date(rows[0].time)) }))
  }, [events, now, timeZone, locale])
  const formats = useMemo(() => ({
    clock: new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit", timeZone }),
    full: new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric", hour: "numeric", minute: "2-digit", timeZone }),
  }), [locale, timeZone])

  const nextReveal = useRef(0)
  const schedule = useCallback(() => {
    if (reduced) return 0
    const current = performance.now() / 1000
    const start = Math.min(Math.max(current, nextReveal.current), current + 0.45)
    nextReveal.current = start + STEP
    return start - current
  }, [reduced])
  const clock = useMemo<Clock>(() => ({ schedule, reduced, fresh: known.fresh }), [schedule, reduced, known.fresh])

  function toggle(rowId: string) {
    setExpanded((current) => {
      const next = new Set(current)
      if (next.has(rowId)) next.delete(rowId)
      else next.add(rowId)
      return next
    })
  }
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return
    const triggers = [...(scrollerRef.current?.querySelectorAll<HTMLElement>("[data-timeline-trigger]") ?? [])]
    const index = triggers.indexOf(document.activeElement as HTMLElement)
    if (index < 0) return
    event.preventDefault()
    const next = event.key === "Home" ? 0 : event.key === "End" ? triggers.length - 1 : Math.min(Math.max(index + (event.key === "ArrowDown" ? 1 : -1), 0), triggers.length - 1)
    triggers[next]?.focus()
  }

  const height = typeof maxHeight === "number" ? `${maxHeight}px` : maxHeight

  return (
    <RevealClock.Provider value={clock}>
      <div data-slot="timeline" role="region" aria-label={label} className={cn("relative grid min-w-0 text-foreground", className, classNames?.root)}>
        <div
          ref={scrollerRef}
          data-slot="timeline-scroller"
          data-scrolls={scrolls || undefined}
          data-more={more || undefined}
          className={cn("relative min-w-0 [overflow-anchor:none]", scrolls && "max-h-(--timeline-height) overflow-y-auto overscroll-contain", classNames?.scroller)}
          style={scrolls ? ({ "--timeline-height": height } as CSSProperties) : undefined}
          onKeyDown={onKeyDown}
        >
          <div ref={trackRef}>
            <AnimatePresence>
              {groups.map((group) => (
                <DaySection key={group.day} id={`${id}-${group.day}`} fresh={!initialDays.has(group.day)} reduced={reduced}>
                  <div data-slot="timeline-day" role="heading" aria-level={headingLevel} id={`${id}-${group.day}`} className={cn("sticky top-0 z-20 flex items-baseline justify-between gap-3 bg-background py-2 pr-3 text-sm font-medium", classNames?.day)}>
                    <span>{group.label}</span>
                    <span className="text-xs font-normal text-muted-foreground tabular-nums" aria-hidden="true">
                      <RollingCount value={group.rows.length} reduced={reduced} /> {group.rows.length === 1 ? "update" : "updates"}
                    </span>
                    <span className="sr-only">{`, ${group.rows.length} ${group.rows.length === 1 ? "update" : "updates"}`}</span>
                  </div>
                  <ol className="m-0 mb-3 list-none p-0">
                    <AnimatePresence>
                      {group.rows.map((row, index) => {
                        const today = group.label === "Today" && now - row.time < 12 * HOUR
                        const time = today ? relative(row.time, now) : { short: formats.clock.format(new Date(row.time)), long: "" }
                        return (
                          <TimelineRow
                            key={row.id}
                            row={row}
                            last={index === group.rows.length - 1}
                            expanded={expanded.has(row.id)}
                            onToggle={() => toggle(row.id)}
                            timeLabel={time.short}
                            timeFull={today ? `${time.long}, ${formats.full.format(new Date(row.time))}` : formats.full.format(new Date(row.time))}
                            classNames={classNames}
                          />
                        )
                      })}
                    </AnimatePresence>
                  </ol>
                </DaySection>
              ))}
            </AnimatePresence>
          </div>
        </div>
        {scrolls && more ? <div className="pointer-events-none absolute inset-x-0 bottom-0 h-9 bg-gradient-to-b from-transparent to-background" aria-hidden="true" /> : null}
        <span className="sr-only" role="status">{known.announcement}</span>
      </div>
    </RevealClock.Provider>
  )
}

