                aria-label={`${playLabel} ${clock(quote.at)}`}
                onClick={() => seek(quote.at)}
              >
                <Play />
              </Button>
              <div className="min-w-0">
                <p className="text-xs text-muted-foreground">
                  {quote.speaker} · {clock(quote.at)}
