export type DateParts = { y: number; m: number; d: number }

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/
const DAY_MS = 86_400_000

export function isFilterOp(value: string): value is FilterOp {
  return (FILTER_OPS as readonly string[]).includes(value)
}

export function parseDateOnly(value: unknown): DateParts | null {
  if (typeof value !== "string") return null
  const match = DATE_RE.exec(value)
  if (!match) return null
  const y = Number(match[1])
  const m = Number(match[2])
  const d = Number(match[3])
  if (m < 1 || m > 12 || d < 1 || d > 31) return null
  const utc = new Date(Date.UTC(y, m - 1, d))
  if (
    utc.getUTCFullYear() !== y ||
    utc.getUTCMonth() !== m - 1 ||
    utc.getUTCDate() !== d
  ) {
    return null
  }
  return { y, m, d }
}

export function formatDateOnly(parts: DateParts): string {
  const m = String(parts.m).padStart(2, "0")
  const d = String(parts.d).padStart(2, "0")
  return `${String(parts.y).padStart(4, "0")}-${m}-${d}`
}

function dateUtc(parts: DateParts): number {
  return Date.UTC(parts.y, parts.m - 1, parts.d)
}

function fromUtc(ms: number): DateParts {
  const date = new Date(ms)
  return { y: date.getUTCFullYear(), m: date.getUTCMonth() + 1, d: date.getUTCDate() }
}

/** Local calendar day for "today". Pass a Date in tests. */
export function localToday(now = new Date()): string {
  return formatDateOnly({
    y: now.getFullYear(),
    m: now.getMonth() + 1,
    d: now.getDate(),
  })
}

export function addDays(iso: string, days: number): string | null {
  const parts = parseDateOnly(iso)
  if (!parts || !Number.isFinite(days)) return null
  return formatDateOnly(fromUtc(dateUtc(parts) + Math.trunc(days) * DAY_MS))
}

export function diffDays(start: string, end: string): number | null {
  const a = parseDateOnly(start)
  const b = parseDateOnly(end)
  if (!a || !b) return null
  return Math.round((dateUtc(b) - dateUtc(a)) / DAY_MS)
}

export function addMonths(iso: string, months: number): string | null {
  const parts = parseDateOnly(iso)
  if (!parts || !Number.isFinite(months)) return null
  const index = parts.y * 12 + (parts.m - 1) + Math.trunc(months)
  const y = Math.floor(index / 12)
  const m = (index % 12) + 1
  const dim = new Date(Date.UTC(y, m, 0)).getUTCDate()
  return formatDateOnly({ y, m, d: Math.min(parts.d, dim) })
}

export function startOfWeek(iso: string, weekStartsOn = 1): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  const weekday = new Date(dateUtc(parts)).getUTCDay()
  const lead = (weekday - weekStartsOn + 7) % 7
  return addDays(iso, -lead)
}

export function startOfMonth(iso: string): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  return formatDateOnly({ y: parts.y, m: parts.m, d: 1 })
}

export function startOfQuarter(iso: string): string | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  const m = Math.floor((parts.m - 1) / 3) * 3 + 1
  return formatDateOnly({ y: parts.y, m, d: 1 })
}

export function weekdayIndex(iso: string): number | null {
  const parts = parseDateOnly(iso)
  if (!parts) return null
  return new Date(dateUtc(parts)).getUTCDay()
}

export function asNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value
  if (typeof value === "string" && value.trim() !== "") {
    const n = Number(value)
    if (Number.isFinite(n)) return n
  }
  return null
}

export function asPerson(value: unknown): PersonValue | null {
  if (typeof value === "string" && value.trim()) return { name: value.trim() }
  if (!value || typeof value !== "object") return null
  const name = (value as { name?: unknown }).name
  if (typeof name !== "string" || !name.trim()) return null
  const avatar = (value as { avatarUrl?: unknown }).avatarUrl
  return {
    name: name.trim(),
    avatarUrl: typeof avatar === "string" ? avatar : undefined,
  }
}

export function asDateRange(value: unknown): DateRangeValue | null {
  if (!value || typeof value !== "object") return null
  const start = (value as { start?: unknown }).start
  const end = (value as { end?: unknown }).end
  if (typeof start !== "string" || typeof end !== "string") return null
  if (!parseDateOnly(start) || !parseDateOnly(end)) return null
  return { start, end }
}

export function isEmptyValue(value: unknown): boolean {
  if (value == null) return true
  if (typeof value === "string") return value.trim() === ""
  if (typeof value === "number") return !Number.isFinite(value)
  if (typeof value === "boolean") return false
  if (asPerson(value)) return false
  if (asDateRange(value)) return false
  return false
}

export function foldText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function fieldById(
  fields: readonly FieldDef[],
  id: string | undefined,
): FieldDef | undefined {
  if (!id) return undefined
  return fields.find((field) => field.id === id)
}

export function titleFieldOf(
  fields: readonly FieldDef[],
  preferred?: string,
): FieldDef | undefined {
  return fieldById(fields, preferred) ?? fields.find((field) => field.type === "text")
}

export function recordTitle(
  record: MultiRecord,
  fields: readonly FieldDef[],
  preferred?: string,
): string {
  const field = titleFieldOf(fields, preferred)
  if (!field) return record.id
  const text = formatFieldValue(record[field.id], field)
  return text || record.id
}

export function optionLabel(field: FieldDef, value: string): string {
  return field.options?.find((option) => option.value === value)?.label ?? value
}

export function optionTone(field: FieldDef, value: string, index = 0): ChartTone {
  const tone = field.options?.find((option) => option.value === value)?.tone
  if (tone) return tone
  const fallback = (index % 5) + 1
  return fallback as ChartTone
}

export function formatCurrency(
  value: number,
  locale?: string,
  currency = "USD",
  format: "compact" | "standard" = "compact",
): string {
  const compact = format === "compact" && Math.abs(value) >= 1000
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    maximumFractionDigits: compact ? 1 : 2,
    minimumFractionDigits: 0,
  }).format(value)
}

export function formatNumber(value: number, locale?: string): string {
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)
}

export function formatDateLabel(iso: string, locale?: string): string {
  const parts = parseDateOnly(iso)
  if (!parts) return ""
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(parts.y, parts.m - 1, parts.d)))
}

export function formatMonthLabel(year: number, monthIndex: number, locale?: string): string {
  return new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, monthIndex, 1)))
}

export function weekdayLabels(locale: string | undefined, weekStartsOn = 1): string[] {
  const monday = new Date(Date.UTC(2026, 0, 5))
  return Array.from({ length: 7 }, (_, index) => {
    const day = new Date(monday.getTime() + ((index + weekStartsOn + 6) % 7) * DAY_MS)
    return new Intl.DateTimeFormat(locale, { weekday: "short", timeZone: "UTC" }).format(day)
  })
}

export function formatFieldValue(
  value: unknown,
  field: FieldDef,
  locale?: string,
): string {
  if (isEmptyValue(value)) return ""
  switch (field.type) {
    case "number":
      return formatNumber(asNumber(value) ?? 0, locale)
    case "currency":
      return formatCurrency(
        asNumber(value) ?? 0,
        locale,
        field.currency,
        field.format ?? "compact",
      )
    case "progress": {
      const n = asNumber(value) ?? 0
      return `${formatNumber(n, locale)}%`
    }
    case "date":
      return formatDateLabel(String(value), locale)
    case "daterange": {
      const range = asDateRange(value)
      if (!range) return ""
      return `${formatDateLabel(range.start, locale)} – ${formatDateLabel(range.end, locale)}`
    }
    case "select":
    case "status":
      return optionLabel(field, String(value))
    case "person":
    case "relation":
      return asPerson(value)?.name ?? ""
    case "boolean":
      return value === true ? "Yes" : "No"
    default:
      return typeof value === "string" ? value : String(value)
  }
}

export function searchText(
  record: MultiRecord,
  fields: readonly FieldDef[],
  locale?: string,
): string {
  const parts = fields.map((field) => formatFieldValue(record[field.id], field, locale))
  parts.push(record.id)
  return foldText(parts.filter(Boolean).join(" "))
}

export function searchRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  query: string,
  locale?: string,
): T[] {
  const needle = foldText(query.trim())
  if (!needle) return [...records]
  return records.filter((record) => searchText(record, fields, locale).includes(needle))
}

function compareClause(
  record: MultiRecord,
  field: FieldDef,
  clause: FilterClause,
  locale?: string,
): boolean {
  const value = record[field.id]
  const empty = isEmptyValue(value)
  switch (clause.op) {
    case "empty":
      return empty
    case "notEmpty":
      return !empty
    case "contains": {
      if (empty) return false
      const hay = foldText(formatFieldValue(value, field, locale))
      return hay.includes(foldText(clause.value ?? ""))
    }
    case "is":
    case "isNot": {
      const expected = clause.value ?? ""
      let same = false
      if (field.type === "number" || field.type === "currency" || field.type === "progress") {
        same = asNumber(value) === asNumber(expected)
      } else if (field.type === "boolean") {
        same = String(value === true) === expected
      } else if (field.type === "person" || field.type === "relation") {
        same = (asPerson(value)?.name ?? "") === expected
      } else {
        same = String(value ?? "") === expected
      }
      return clause.op === "is" ? same : !same
    }
    case "gt":
    case "lt": {
      const left = asNumber(value)
      const right = asNumber(clause.value)
      if (left == null || right == null) return false
      return clause.op === "gt" ? left > right : left < right
    }
    case "before":
    case "after": {
      const iso = typeof value === "string" ? value : asDateRange(value)?.start
      if (!iso || !clause.value || !parseDateOnly(iso) || !parseDateOnly(clause.value)) return false
      return clause.op === "before" ? iso < clause.value : iso > clause.value
    }
    default:
      return true
  }
}

export function filterRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  filters: readonly FilterClause[],
  locale?: string,
): T[] {
  if (!filters.length) return [...records]
  return records.filter((record) =>
    filters.every((clause) => {
      const field = fieldById(fields, clause.field)
      if (!field) return true
      return compareClause(record, field, clause, locale)
    }),
  )
}

function sortValue(record: MultiRecord, field: FieldDef): string | number | null {
  const value = record[field.id]
  if (isEmptyValue(value)) return null
  if (field.type === "number" || field.type === "currency" || field.type === "progress") {
    return asNumber(value)
  }
  if (field.type === "boolean") return value === true ? 1 : 0
  if (field.type === "date") return typeof value === "string" ? value : null
  if (field.type === "daterange") return asDateRange(value)?.start ?? null
  if (field.type === "person" || field.type === "relation") return asPerson(value)?.name ?? null
  if (field.type === "select" || field.type === "status") return optionLabel(field, String(value))
  return String(value)
}

export function compareFieldValues(
  left: MultiRecord,
  right: MultiRecord,
  field: FieldDef,
  direction: SortDirection,
  locale?: string,
): number {
  const a = sortValue(left, field)
  const b = sortValue(right, field)
  if (a == null && b == null) return 0
  if (a == null) return 1
  if (b == null) return -1
  let result = 0
  if (typeof a === "number" && typeof b === "number") result = a - b
  else result = String(a).localeCompare(String(b), locale, { numeric: true, sensitivity: "base" })
  return direction === "asc" ? result : -result
}

export function sortRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  sort: SortClause | null | undefined,
  locale?: string,
): T[] {
  if (!sort) return [...records]
  const field = fieldById(fields, sort.field)
  if (!field) return [...records]
  return records
    .map((record, index) => ({ record, index }))
    .sort((a, b) => {
      const result = compareFieldValues(a.record, b.record, field, sort.direction, locale)
      return result || a.index - b.index
    })
    .map((entry) => entry.record)
}

export function groupKey(record: MultiRecord, field: FieldDef): string {
  const value = record[field.id]
  if (isEmptyValue(value)) return ""
  if (field.type === "person" || field.type === "relation") return asPerson(value)?.name ?? ""
  if (field.type === "boolean") return value === true ? "true" : "false"
  return String(value)
}

export function groupRecords<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  fieldId: string | null | undefined,
  options?: { includeEmpty?: boolean; emptyLabel?: string; locale?: string },
): RecordGroup<T>[] {
  const field = fieldById(fields, fieldId ?? undefined)
  if (!field) {
    return [{ key: "", label: options?.emptyLabel ?? "All", records: [...records], sum: null }]
  }
  const buckets = new Map<string, T[]>()
  for (const record of records) {
    const key = groupKey(record, field)
    const list = buckets.get(key)
    if (list) list.push(record)
    else buckets.set(key, [record])
  }
  const keys: string[] = []
  if (field.options?.length) {
    for (const option of field.options) keys.push(option.value)
  }
  if (field.type === "boolean") keys.push("true", "false")
  for (const key of buckets.keys()) {
    if (!keys.includes(key)) keys.push(key)
  }
  if (!keys.includes("") && buckets.has("")) keys.push("")

  const emptyLabel = options?.emptyLabel ?? "Empty"
  return keys.filter((key) => options?.includeEmpty || (buckets.get(key)?.length ?? 0) > 0)
    .map((key) => ({
      key,
      label: key === "" ? emptyLabel : labelForGroup(field, key),
      records: buckets.get(key) ?? [],
      sum: null,
    }))
}

function labelForGroup(field: FieldDef, key: string): string {
  if (field.type === "boolean") return key === "true" ? "Yes" : "No"
  if (field.type === "select" || field.type === "status") return optionLabel(field, key)
  return key
}

export function sumField(
  records: readonly MultiRecord[],
  field: FieldDef | undefined,
): number | null {
  if (!field) return null
  let total = 0
  let any = false
  for (const record of records) {
    const n = asNumber(record[field.id])
    if (n == null) continue
    total += n
    any = true
  }
  return any ? total : null
}

export function groupRecordsWithSum<T extends MultiRecord>(
  records: readonly T[],
  fields: readonly FieldDef[],
  fieldId: string | null | undefined,
  sumFieldId: string | undefined,
  options?: { includeEmpty?: boolean; emptyLabel?: string; locale?: string },
): RecordGroup<T>[] {
  const groups = groupRecords(records, fields, fieldId, options)
  const metric = fieldById(fields, sumFieldId)
  return groups.map((group) => ({ ...group, sum: sumField(group.records, metric) }))
}

/** Six weeks, Monday-first unless `weekStartsOn` says otherwise. `monthIndex` is 0–11. */
export function monthGrid(year: number, monthIndex: number, weekStartsOn = 1): CalendarDay[] {
  const first = formatDateOnly({ y: year, m: monthIndex + 1, d: 1 })
  const origin = startOfWeek(first, weekStartsOn) ?? first
  const days: CalendarDay[] = []
  for (let index = 0; index < 42; index += 1) {
    const iso = addDays(origin, index) ?? origin
    const parts = parseDateOnly(iso)
    days.push({
      iso,
      inMonth: Boolean(parts && parts.y === year && parts.m === monthIndex + 1),
    })
  }
  return days
}

export function chunkWeeks(days: readonly CalendarDay[]): CalendarDay[][] {
  const weeks: CalendarDay[][] = []
  for (let index = 0; index < days.length; index += 7) weeks.push(days.slice(index, index + 7))
  return weeks
}

export function shiftIso(iso: string, zoom: TimelineZoom, units: number): string | null {
  if (zoom === "day") return addDays(iso, units)
  if (zoom === "week") return addDays(iso, units * 7)
  if (zoom === "month") return addMonths(iso, units)
  return addMonths(iso, units * 3)
}

export function snapToUnit(iso: string, zoom: TimelineZoom, weekStartsOn = 1): string | null {
  if (!parseDateOnly(iso)) return null
  if (zoom === "day") return iso
  if (zoom === "week") return startOfWeek(iso, weekStartsOn)
  if (zoom === "month") return startOfMonth(iso)
  return startOfQuarter(iso)
}

export function unitsBetween(
  start: string,
  end: string,
  zoom: TimelineZoom,
  weekStartsOn = 1,
): number | null {
  const a = snapToUnit(start, zoom, weekStartsOn)
  const b = snapToUnit(end, zoom, weekStartsOn)
  if (!a || !b) return null
  if (zoom === "day" || zoom === "week") {
    const days = diffDays(a, b)
    if (days == null) return null
    return zoom === "day" ? days : Math.round(days / 7)
  }
  const pa = parseDateOnly(a)
  const pb = parseDateOnly(b)
  if (!pa || !pb) return null
  const months = (pb.y - pa.y) * 12 + (pb.m - pa.m)
  return zoom === "month" ? months : Math.round(months / 3)
}

/** Inclusive range. A same-day bar still occupies one unit. */
export function barPlacement(
  rangeStart: string,
  start: string,
  end: string,
  zoom: TimelineZoom,
  weekStartsOn = 1,
): { offset: number; span: number } | null {
  const offset = unitsBetween(rangeStart, start, zoom, weekStartsOn)
  const raw = unitsBetween(start, end, zoom, weekStartsOn)
  if (offset == null || raw == null) return null
  return { offset, span: Math.max(1, raw + 1) }
}

export function moveRange(
  start: string,
  end: string,
  zoom: TimelineZoom,
  units: number,
): { start: string; end: string } | null {
  const nextStart = shiftIso(start, zoom, units)
  const nextEnd = shiftIso(end, zoom, units)
  if (!nextStart || !nextEnd) return null
  return { start: nextStart, end: nextEnd }
}

export function resizeRange(
  start: string,
  end: string,
  edge: "start" | "end",
  zoom: TimelineZoom,
  units: number,
): { start: string; end: string } | null {
  if (edge === "end") {
    const next = shiftIso(end, zoom, units)
    if (!next) return null
    if ((diffDays(start, next) ?? -1) < 0) return { start, end: start }
    return { start, end: next }
  }
  const next = shiftIso(start, zoom, units)
  if (!next) return null
  if ((diffDays(next, end) ?? -1) < 0) return { start: end, end }
  return { start: next, end }
}

export function timelineRange(
  records: readonly MultiRecord[],
  startField: string,
  endField: string,
  zoom: TimelineZoom,
  today: string,
  weekStartsOn = 1,
): { start: string; end: string } {
  let min = today
  let max = today
  for (const record of records) {
    const start = record[startField]
    const end = record[endField]
    if (typeof start === "string" && parseDateOnly(start) && start < min) min = start
    if (typeof end === "string" && parseDateOnly(end) && end > max) max = end
  }
  const paddedStart = shiftIso(min, zoom, -1) ?? min
  const paddedEnd = shiftIso(max, zoom, 1) ?? max
  return {
    start: snapToUnit(paddedStart, zoom, weekStartsOn) ?? paddedStart,
    end: snapToUnit(paddedEnd, zoom, weekStartsOn) ?? paddedEnd,
  }
}

export function timelineTicks(
  start: string,
  end: string,
  zoom: TimelineZoom,
  locale?: string,
  weekStartsOn = 1,
): TimelineTick[] {
  const ticks: TimelineTick[] = []
  let cursor = snapToUnit(start, zoom, weekStartsOn)
  const limit = 400
  while (cursor && cursor <= end && ticks.length < limit) {
    ticks.push({ iso: cursor, label: tickLabel(cursor, zoom, locale) })
    cursor = shiftIso(cursor, zoom, 1)
  }
  return ticks
}

function tickLabel(iso: string, zoom: TimelineZoom, locale?: string): string {
  const parts = parseDateOnly(iso)
  if (!parts) return iso
  const date = new Date(Date.UTC(parts.y, parts.m - 1, parts.d))
  if (zoom === "day") {
    return new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" }).format(date)
  }
  if (zoom === "week") {
    return new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" }).format(date)
  }
  if (zoom === "month") {
    return new Intl.DateTimeFormat(locale, { month: "short", timeZone: "UTC" }).format(date)
  }
  const quarter = Math.floor((parts.m - 1) / 3) + 1
  return `Q${quarter} ${parts.y}`
}

export function recordsToCsv(
  records: readonly MultiRecord[],
  fields: readonly FieldDef[],
  locale?: string,
): string {
  const columns: CsvColumn[] = fields.map((field) => ({ key: field.id, header: field.label }))
  const rows = records.map((record) => {
    const row: Record<string, unknown> = {}
    for (const field of fields) row[field.id] = formatFieldValue(record[field.id], field, locale)
    return row
  })
  return toCsv(rows, columns)
}

export function encodeFilters(filters: readonly FilterClause[]): string {
  return filters
    .map((clause) =>
      [clause.field, clause.op, clause.value ?? ""].map((part) => encodeURIComponent(part)).join("~"),
    )
    .join("|")
}

export function decodeFilters(raw: string | null | undefined): FilterClause[] {
  if (!raw) return []
  const clauses: FilterClause[] = []
  for (const part of raw.split("|")) {
    if (!part) continue
    const [fieldRaw, opRaw, valueRaw = ""] = part.split("~")
    if (!fieldRaw || !opRaw) continue
    const field = decodeURIComponent(fieldRaw)
    const op = decodeURIComponent(opRaw)
    if (!isFilterOp(op)) continue
    clauses.push({
      id: `url-${clauses.length}`,
      field,
      op,
      value: decodeURIComponent(valueRaw),
    })
  }
  return clauses
}

export function encodeSort(sort: SortClause | null | undefined): string | null {
  if (!sort) return null
  return `${sort.field}:${sort.direction}`
}

export function decodeSort(raw: string | null | undefined): SortClause | null {
  if (!raw) return null
  const split = raw.indexOf(":")
  if (split < 1) return null
  const field = raw.slice(0, split)
  const direction = raw.slice(split + 1)
  if (direction !== "asc" && direction !== "desc") return null
  return { field, direction }
}

export function draftFromFormData(
  formData: FormData,
  fields: readonly FieldDef[],
): Record<string, unknown> {
  const draft: Record<string, unknown> = {}
  for (const field of fields) {
    if (field.readOnly) continue
    if (field.type === "boolean") {
      const raw = formData.get(field.id)
      draft[field.id] = raw === "true" || raw === "on"
      continue
    }
    if (field.type === "daterange") {
      const start = formData.get(field.id)
      const end = formData.get(`${field.id}__end`)
      if (typeof start === "string" && start && typeof end === "string" && end) {
        draft[field.id] = { start, end }
      }
      continue
    }
    const raw = formData.get(field.id)
    if (typeof raw !== "string" || raw.trim() === "") continue
    if (field.type === "number" || field.type === "currency" || field.type === "progress") {
      draft[field.id] = Number(raw)
      continue
    }
    draft[field.id] = raw
  }
  return draft
}

export function validateDraft(
  draft: Record<string, unknown>,
  fields: readonly FieldDef[],
  titleField?: string,
): string | null {
  const title = titleFieldOf(fields, titleField)
  if (title && !title.readOnly) {
    const value = draft[title.id]
    if (typeof value !== "string" || !value.trim()) return `${title.label} is required`
  }
  for (const field of fields) {
    if (field.type !== "number" && field.type !== "currency" && field.type !== "progress") continue
    const value = draft[field.id]
    if (value == null || value === "") continue
    if (typeof value === "number" && !Number.isFinite(value)) return `${field.label} must be a number`
    if (typeof value === "string" && value.trim() !== "" && !Number.isFinite(Number(value))) {
      return `${field.label} must be a number`
    }
  }
  return null
}

export function createRecordId(prefix = "rec"): string {
  return `${prefix}_${Math.random().toString(36).slice(2, 10)}`
}

export const VIEW_PERSISTENCE_SCOPES = ["global", "project"] as const

export type ViewPersistenceScope = (typeof VIEW_PERSISTENCE_SCOPES)[number]

/** Storage key for which views are enabled. The id is the collection, not a record. */
export function viewPersistenceKey(scope: ViewPersistenceScope, id: string): string {
  const safe = id.replace(/[^a-zA-Z0-9._-]/g, "")
  return `retana.views.${scope}.${safe || "default"}`
}

/**
 * Keeps enabled view ids inside `allowed`, in that order.
 * An empty result falls back to the previous set, then to the first allowed id.
 */
export function coerceEnabledViews(
  next: readonly string[],
  allowed: readonly string[],
  previous?: readonly string[],
): string[] {
  const allow = new Set(allowed)
  const picked = new Set(next.filter((id) => allow.has(id)))
  const ordered = allowed.filter((id) => picked.has(id))
  if (ordered.length > 0) return ordered
  if (previous) {
    const kept = allowed.filter((id) => previous.includes(id))
    if (kept.length > 0) return kept
  }
  return allowed[0] ? [allowed[0]] : []
}

/** Parses a stored id list. `null` means the value is missing or unreadable. */
export function readEnabledViews(
  raw: string | null | undefined,
  allowed: readonly string[],
): string[] | null {
  if (!raw) return null
  try {
    const parsed = JSON.parse(raw) as unknown
    if (!Array.isArray(parsed) || !parsed.every((id) => typeof id === "string")) return null
    const next = coerceEnabledViews(parsed, allowed)
    return next.length > 0 ? next : null
  } catch {
    return null
  }
}

export type CsvColumn = {
  key: string
  header: string
}

export function escapeCsvCell(value: unknown): string {
  if (value == null) return ""
  let text = String(value)
  // Spreadsheets treat a leading = + - @ tab or line break as a formula.
  if (typeof value === "string" && /^[=+\-@\t\r\n]/.test(text)) text = `'${text}`
  if (/[",\n\r']/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

export function toCsv(
  rows: readonly Record<string, unknown>[],
  columns: readonly CsvColumn[],
): string {
  const head = columns.map((column) => escapeCsvCell(column.header)).join(",")
  const body = rows
    .map((row) => columns.map((column) => escapeCsvCell(row[column.key])).join(","))
    .join("\n")
  return body ? `${head}\n${body}` : head
}

export function downloadCsv(filename: string, csv: string) {
  if (typeof document === "undefined") return
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename.endsWith(".csv") ? filename : `${filename}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

"use client"

/** Adapted from Arc UI (MIT). */

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react"
import type { FocusEvent, KeyboardEvent, MouseEvent, PointerEvent as ReactPointerEvent, ReactNode } from "react"
import { AnimatePresence, animate, motion, useIsPresent, useMotionValue, usePresence, useReducedMotion, useTransform } from "motion/react"
import type { HTMLMotionProps, MotionProps, TargetAndTransition, Transition } from "motion/react"
import { CircleCheck, CircleX, Info, TriangleAlert, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type ToastType = "success" | "info" | "warning" | "error" | "loading"

export type ToastAppearance = "default" | "undo"

export interface ToastAction {
  label: string
  /** Runs the action. The toast closes afterwards unless the handler updates it, so an Undo can morph the toast into its result. */
  onClick: (id: string) => void
}

export interface ToastOptions {
  /** Reuse an id to update a toast in place instead of stacking a new one. */
  id?: string
  type?: ToastType
  /** Dark pill with an undo action. Pauses with the rest of the stack and lasts 6 seconds unless duration is set. */
  appearance?: ToastAppearance
  title: string
  description?: string
  action?: ToastAction
  /** Milliseconds before the toast closes itself. Defaults by type; loading toasts wait for an update. Pass Infinity to keep it until closed. */
  duration?: number
}

export interface ToastStackApi {
  /** Shows a toast and returns its id. */
  toast: (options: ToastOptions) => string
  /** Morphs a toast in place: icon, copy, and height animate to the new content and its timer restarts. Pass `action: undefined` to remove the action. */
  update: (id: string, patch: Partial<Omit<ToastOptions, "id">>) => void
  /** Dismisses one toast, or every toast when called without an id. */
  dismiss: (id?: string) => void
}

export interface ToastStackProviderProps {
  children: ReactNode
  /** Base lifetime in milliseconds. Warnings and errors stay 1.6 times longer. */
  duration?: number
  /** Oldest toasts beyond this count are dropped from the queue. */
  limit?: number
}

/**
 * The viewport for a toast stack. Render it once inside a `ToastStackProvider` and call `useToastStack()` anywhere below.
 * Use it for short, non-blocking results of what someone just did: new toasts rise from the bottom edge, older ones tuck behind,
 * and hovering or focusing the stack fans it out into a list. Toasts pause while the stack is open or the tab is hidden, and swipe right to dismiss.
 */
export interface ToastStackProps {
  /** Accessible name of the notification region. */
  label?: string
  position?: "bottom-right" | "bottom-center" | "bottom-left"
  /** Pins the stack inside the nearest positioned ancestor instead of the window, for panels and previews. */
  contained?: boolean
  /** How many toasts show at once. Older ones wait behind and return as the front ones close. */
  visibleToasts?: number
  /** Alt+T moves focus into the stack. */
  hotkey?: boolean
  className?: string
  classNames?: ToastStackClassNames
}

export type ToastStackClassNames = {
  root?: string
  list?: string
  item?: string
  card?: string
  title?: string
  description?: string
  action?: string
  close?: string
}

type ToastRecord = { id: string; type: ToastType; appearance: ToastAppearance; title: string; description?: string; action?: ToastAction; duration: number; seq: number; version: number }
type ToastStore = ToastStackApi & { subscribe: (listener: () => void) => () => void; getSnapshot: () => ToastRecord[]; runAction: (id: string) => void }
type Target = { y: number; scale: number; height: number; opacity: number; content: number }

const PEEK = 14
const GAP = 12
const STEP = 0.05
const BORDER = 2
const SWIPE_FADE = 280
const EMPTY: ToastRecord[] = []
const typeLabels: Record<ToastType, string> = { success: "Success", info: "Info", warning: "Warning", error: "Error", loading: "In progress" }
const icons = { success: CircleCheck, info: Info, warning: TriangleAlert, error: CircleX }
const typeColor: Record<ToastType, string> = {
  success: "text-[color:var(--chart-2)]",
  info: "text-primary",
  warning: "text-[color:var(--chart-4)]",
  error: "text-destructive",
  loading: "text-muted-foreground",
}

const standard = [...motionPresets.ease.standard] as [number, number, number, number]
const enterEase = [...motionPresets.ease.enter] as [number, number, number, number]
const fade: Transition = { duration: motionPresets.duration.fast, ease: standard }
const enterFade: Transition = { duration: motionPresets.duration.standard, ease: enterEase }
const reducedFade: Transition = { duration: 0.15, ease: standard }
const exitFast: Transition = { duration: motionPresets.duration.fast, ease: standard }
const textIn: TargetAndTransition = { opacity: 0, y: "0.3em", filter: `blur(${motionPresets.blur.soft}px)` }
const textOut: TargetAndTransition = { opacity: 0, y: "-0.3em", filter: `blur(${motionPresets.blur.subtle}px)`, transition: exitFast }
const iconIn: TargetAndTransition = { opacity: 0, scale: 0.6, filter: `blur(${motionPresets.blur.subtle}px)` }
const shown: TargetAndTransition = { opacity: 1, y: "0em", scale: 1, filter: "blur(0px)" }
const fadeOnly: MotionProps = { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0, transition: reducedFade }, transition: reducedFade }
const textSwap: MotionProps = { initial: textIn, animate: shown, exit: textOut, transition: { duration: 0.22, ease: enterEase } }
const iconSwap: MotionProps = { initial: iconIn, animate: shown, exit: { ...iconIn, transition: exitFast }, transition: { ...motionPresets.spring.snappy, opacity: fade, filter: fade } }

const durationFor = (type: ToastType, base: number) => (type === "loading" ? Infinity : type === "warning" || type === "error" ? base * 1.6 : base)
const project = (velocity: number) => (velocity / 1000) * (0.99 / (1 - 0.99))
const rubberBand = (distance: number, dimension: number) => (1 - 1 / ((distance * 0.55) / dimension + 1)) * dimension
const subscribeVisibility = (listener: () => void) => {
  document.addEventListener("visibilitychange", listener)
  return () => document.removeEventListener("visibilitychange", listener)
}
const getServerSnapshot = () => EMPTY
const focusVisible = (element: Element) => {
  try {
    return element.matches(":focus-visible")
  } catch {
    return true
  }
}

function layoutStack(toasts: ToastRecord[], heights: Record<string, number>, expanded: boolean, visibleToasts: number) {
  const front = toasts.length ? heights[toasts[0].id] ?? 0 : 0
  const tops = toasts.reduce<number[]>((sum, _item, index) => [...sum, sum[index] + (index < visibleToasts ? (heights[toasts[index].id] ?? 0) + GAP : 0)], [0])
  const targets = toasts.map((item, index): Target => {
    const visible = index < visibleToasts
    const depth = Math.min(index, visibleToasts)
    return expanded
      ? { y: -tops[index], scale: 1, height: heights[item.id] ?? 0, opacity: visible ? 1 : 0, content: 1 }
      : { y: -PEEK * depth, scale: 1 - STEP * depth, height: index === 0 ? heights[item.id] ?? 0 : front, opacity: visible ? 1 : 0, content: index === 0 ? 1 : 0 }
  })
  const listHeight = !toasts.length ? 0 : expanded ? tops[toasts.length] - GAP : front + PEEK * (Math.min(toasts.length, visibleToasts) - 1)
  return { targets, listHeight }
}

function createToastStore(base: number, limit: number): ToastStore {
  let toasts: ToastRecord[] = []
  let seq = 0
  const listeners = new Set<() => void>()
  const commit = (next: ToastRecord[]) => {
    toasts = next
    listeners.forEach((listener) => listener())
  }
  const update: ToastStackApi["update"] = (id, patch) => {
    const found = toasts.find((item) => item.id === id)
    if (!found) return
    const type = patch.type ?? found.type
    const appearance = patch.appearance ?? found.appearance
    const record: ToastRecord = {
      ...found,
      ...patch,
      type,
      appearance,
      duration: patch.duration ?? (appearance === "undo" ? 6000 : durationFor(type, base)),
      version: found.version + 1,
    }
    commit(toasts.map((item) => (item.id === id ? record : item)))
  }
  const toast: ToastStackApi["toast"] = ({ id, ...options }) => {
    if (id && toasts.some((item) => item.id === id)) {
      update(id, options)
      return id
    }
    const type = options.type ?? "info"
    const appearance = options.appearance ?? "default"
    seq += 1
    const record: ToastRecord = {
      ...options,
      id: id ?? `toast-${seq}`,
      type,
      appearance,
      duration: options.duration ?? (appearance === "undo" ? 6000 : durationFor(type, base)),
      seq,
      version: 0,
    }
    commit([record, ...toasts].slice(0, limit))
    return record.id
  }
  const dismiss: ToastStackApi["dismiss"] = (id) => {
    if (id === undefined) {
      if (toasts.length) commit([])
      return
    }
    if (toasts.some((item) => item.id === id)) commit(toasts.filter((item) => item.id !== id))
  }
  const runAction = (id: string) => {
    const found = toasts.find((item) => item.id === id)
    if (!found?.action) return
    found.action.onClick(id)
    if (toasts.find((item) => item.id === id)?.version === found.version) dismiss(id)
  }
  return {
    toast,
    update,
    dismiss,
    runAction,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    getSnapshot: () => toasts,
  }
}

const ToastStackContext = createContext<ToastStore | null>(null)

function useStore() {
  const store = useContext(ToastStackContext)
  if (!store) throw new Error("Render toast stack consumers inside <ToastStackProvider>.")
  return store
}

/** Scopes a toast queue to its subtree, so two stacks on one page never share toasts. */
export function ToastStackProvider({ children, duration = 5000, limit = 12 }: ToastStackProviderProps) {
  const [store] = useState(() => createToastStore(duration, limit))
  return <ToastStackContext.Provider value={store}>{children}</ToastStackContext.Provider>
}

/** Shows, updates, and dismisses toasts from anywhere inside the provider. `count` is how many toasts are queued. */
export function useToastStack(): ToastStackApi & { count: number } {
  const store = useStore()
  const count = useSyncExternalStore(store.subscribe, () => store.getSnapshot().length, () => 0)
  return { toast: store.toast, update: store.update, dismiss: store.dismiss, count }
}

function Swap(props: HTMLMotionProps<"span">) {
  const present = useIsPresent()
  return <motion.span {...props} aria-hidden={present ? props["aria-hidden"] : true} />
}

type Gesture = { pointerId: number; startX: number; startY: number; origin: number; active: boolean; samples: { t: number; x: number }[] }

interface ToastItemProps {
  toast: ToastRecord
  target: Target
  expanded: boolean
  front: boolean
  hidden: boolean
  paused: boolean
  reduce: boolean
  store: ToastStore
  classNames?: ToastStackClassNames
  onMeasure: (id: string, height: number) => void
  onDragChange: (dragging: boolean) => void
  onTap: () => void
  onHandOff: (leaving: HTMLElement, keyboard: boolean) => void
}

function ToastItem({ toast, target, expanded, front, hidden, paused, reduce, store, classNames, onMeasure, onDragChange, onTap, onHandOff }: ToastItemProps) {
  const { id } = toast
  const [isPresent, safeToRemove] = usePresence()
  const itemRef = useRef<HTMLLIElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const actionRef = useRef<HTMLDivElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const y = useMotionValue(0)
  const scale = useMotionValue(1)
  const height = useMotionValue(0)
  const opacity = useMotionValue(0)
  const contentOpacity = useMotionValue(1)
  const x = useMotionValue(0)
  const swipeFade = useTransform(x, (value) => (value > 0 ? 1 - Math.min(value / SWIPE_FADE, 1) * 0.75 : 1))
  const applied = useRef<boolean | null>(null)
  const swiped = useRef(false)
  const remaining = useRef(toast.duration)
  const gesture = useRef<Gesture | null>(null)
  const suppressClick = useRef(false)
  const pointerType = useRef("mouse")

  useLayoutEffect(() => {
    const node = contentRef.current
    if (!node) return
    onMeasure(id, node.offsetHeight + BORDER)
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => onMeasure(id, node.offsetHeight + BORDER))
    observer.observe(node)
    return () => observer.disconnect()
  }, [id, onMeasure])

  useLayoutEffect(() => {
    if (!isPresent || target.height <= 0) return
    const entering = applied.current === null
    const morph = !entering && applied.current !== expanded
    applied.current = expanded
    if (reduce) {
      y.jump(target.y)
      scale.jump(target.scale)
      height.jump(target.height)
      animate(opacity, target.opacity, reducedFade)
      animate(contentOpacity, target.content, reducedFade)
      return
    }
    if (entering) {
      y.jump(target.y + target.height)
      scale.jump(target.scale)
      height.jump(target.height)
      contentOpacity.jump(target.content)
      opacity.jump(0)
    }
    const spring = morph ? motionPresets.spring.morph : motionPresets.spring.smooth
    animate(y, target.y, spring)
    animate(scale, target.scale, spring)
    if (!entering) animate(height, target.height, spring)
    animate(opacity, target.opacity, entering ? enterFade : fade)
    animate(contentOpacity, target.content, fade)
  }, [contentOpacity, expanded, height, isPresent, opacity, reduce, scale, target.content, target.height, target.opacity, target.scale, target.y, y])

  useEffect(() => {
    remaining.current = toast.duration
  }, [toast.version, toast.duration])
  useEffect(() => {
    if (!isPresent || paused || !Number.isFinite(remaining.current) || toast.duration <= 0) return
    const started = performance.now()
    const timer = window.setTimeout(() => store.dismiss(id), Math.max(remaining.current, 0))
    return () => {
      window.clearTimeout(timer)
      remaining.current -= performance.now() - started
    }
  }, [id, isPresent, paused, store, toast.version, toast.duration])

  useEffect(() => {
    if (isPresent) return
    const node = itemRef.current
    if (node) {
      const active = document.activeElement
      if (active instanceof HTMLElement && node.contains(active)) onHandOff(node, focusVisible(active))
      node.setAttribute("inert", "")
    }
    const done = () => safeToRemove?.()
    if (reduce) {
      void animate(opacity, 0, reducedFade).then(done)
      return
    }
    if (!swiped.current) {
      animate(y, y.get() + 10, motionPresets.spring.smooth)
      animate(scale, scale.get() * 0.96, motionPresets.spring.smooth)
    }
    void animate(opacity, 0, { duration: swiped.current ? 0.22 : motionPresets.duration.exit, ease: standard }).then(done)
  }, [isPresent, onHandOff, opacity, reduce, safeToRemove, scale, y])

  function onPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    pointerType.current = event.pointerType
    suppressClick.current = false
    if (event.button !== 0 || !isPresent || (event.target as Element).closest("button, a")) return
    x.stop()
    gesture.current = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, origin: x.get(), active: false, samples: [] }
  }

  function onPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const current = gesture.current
    if (!current || current.pointerId !== event.pointerId) return
    if (!current.active) {
      const dx = event.clientX - current.startX
      const dy = event.clientY - current.startY
      if (Math.hypot(dx, dy) < 6) return
      if (Math.abs(dy) > Math.abs(dx)) {
        gesture.current = null
        return
      }
      current.active = true
      current.startX = event.clientX
      suppressClick.current = true
      event.currentTarget.setPointerCapture(event.pointerId)
      event.currentTarget.dataset.dragging = ""
      window.getSelection()?.removeAllRanges()
      onDragChange(true)
    }
    const raw = current.origin + event.clientX - current.startX
    x.set(raw >= 0 ? raw : -rubberBand(-raw, event.currentTarget.offsetWidth))
    current.samples.push({ t: event.timeStamp, x: raw })
    while (current.samples.length > 2 && event.timeStamp - current.samples[0].t > 100) current.samples.shift()
  }

  function onPointerEnd(event: ReactPointerEvent<HTMLDivElement>, cancelled: boolean) {
    const current = gesture.current
    if (!current || current.pointerId !== event.pointerId) return
    gesture.current = null
    if (!current.active) return
    delete event.currentTarget.dataset.dragging
    onDragChange(false)
    const first = current.samples[0]
    const last = current.samples[current.samples.length - 1]
    const velocity = cancelled || !first || !last || last.t === first.t || event.timeStamp - last.t > 60 ? 0 : ((last.x - first.x) / (last.t - first.t)) * 1000
    const width = event.currentTarget.offsetWidth
    const offset = x.get()
    if (!cancelled && offset > 0 && velocity > -200 && offset + project(velocity) > width * 0.4) {
      swiped.current = true
      if (!reduce) animate(x, width + 40, { type: "spring", visualDuration: 0.32, bounce: 0, velocity: Math.max(velocity, 0) })
      store.dismiss(id)
      return
    }
    if (reduce) x.jump(0)
    else animate(x, 0, { ...motionPresets.spring.snappy, velocity: offset < 0 ? velocity * 0.3 : velocity })
  }

  function onCardClick(event: MouseEvent<HTMLDivElement>) {
    if (suppressClick.current) {
      suppressClick.current = false
      return
    }
    if (pointerType.current !== "mouse" && !(event.target as Element).closest("button, a")) onTap()
  }

  function runAction(event: MouseEvent<HTMLButtonElement>) {
    const keyboard = focusVisible(event.currentTarget)
    store.runAction(id)
    if (keyboard && !store.getSnapshot().find((item) => item.id === id)?.action) closeRef.current?.focus()
  }

  function onKeyDown(event: KeyboardEvent<HTMLLIElement>) {
    if (event.key !== "Escape") return
    event.stopPropagation()
    store.dismiss(id)
  }

  const markMoving = (moving: boolean) => {
    if (actionRef.current) actionRef.current.dataset.moving = moving ? "true" : "false"
  }
  const Icon = toast.type === "loading" ? null : icons[toast.type]
  const swap = reduce ? fadeOnly : textSwap

  return (
    <motion.li ref={itemRef} data-slot="toast-stack-item" role={toast.appearance === "undo" ? "status" : undefined} className={cn("absolute inset-x-0 bottom-0 origin-top", classNames?.item)} style={{ y, scale, height, opacity, zIndex: toast.seq }} data-front={front} data-expanded={expanded} inert={hidden} onKeyDown={onKeyDown}>
      <motion.div
        data-slot="toast-stack-card"
        data-appearance={toast.appearance}
        className={cn(
          "@container absolute inset-0 overflow-hidden rounded-xl border border-border bg-popover text-foreground shadow-md touch-pan-y data-[dragging]:cursor-grabbing data-[dragging]:select-none",
          !front && !expanded && "bg-muted",
          (front || expanded) && "shadow-lg",
          toast.appearance === "undo" && "rounded-full border-transparent bg-primary text-primary-foreground",
          classNames?.card,
        )}
        style={{ x, opacity: swipeFade }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={(event) => onPointerEnd(event, false)}
        onPointerCancel={(event) => onPointerEnd(event, true)}
        onClick={onCardClick}
      >
        <motion.div ref={contentRef} className="flex items-start gap-3 py-3 pr-3 pl-4" style={{ opacity: contentOpacity }}>
          <span className={cn("relative grid h-5 w-[18px] shrink-0 place-items-center text-muted-foreground", typeColor[toast.type])} aria-hidden="true">
            <AnimatePresence mode="popLayout" initial={false}>
              <Swap key={toast.type} className="col-start-1 row-start-1 grid place-items-center" {...(reduce ? fadeOnly : iconSwap)}>
                {Icon ? <Icon width={18} height={18} strokeWidth={1.75} /> : <span className="block size-4 animate-spin rounded-full border-2 border-current border-r-transparent motion-reduce:animate-none" />}
              </Swap>
            </AnimatePresence>
          </span>
          <div className="relative min-w-0 flex-1 text-sm leading-5">
            <span className="sr-only">{typeLabels[toast.type]}: </span>
            <span data-slot="toast-stack-title" className={cn("relative block font-medium", classNames?.title)}>
              <AnimatePresence mode="popLayout" initial={false}>
                <Swap key={toast.title} className="block" {...swap}>{toast.title}</Swap>
              </AnimatePresence>
            </span>
            <AnimatePresence mode="popLayout" initial={false}>
              {toast.description ? <Swap key={toast.description} data-slot="toast-stack-description" className={cn("mt-0.5 block", toast.appearance === "undo" ? "text-primary-foreground/80" : "text-muted-foreground", classNames?.description)} {...swap}>{toast.description}</Swap> : null}
            </AnimatePresence>
          </div>
          <AnimatePresence initial={false}>
            {toast.action ? (
              <motion.div
                key="action"
                ref={actionRef}
                className="-mt-1 flex shrink-0 justify-end data-[moving=true]:overflow-hidden @max-[21rem]:order-1 @max-[21rem]:mt-0 @max-[21rem]:basis-full @max-[21rem]:justify-start @max-[21rem]:pl-[calc(18px+0.75rem)]"
                initial={reduce ? { opacity: 0 } : { width: 0, opacity: 0 }}
                animate={{ width: "auto", opacity: 1 }}
                exit={reduce ? { opacity: 0 } : { width: 0, opacity: 0 }}
                transition={reduce ? reducedFade : { width: motionPresets.spring.smooth, opacity: fade }}
                onAnimationStart={() => markMoving(true)}
                onAnimationComplete={() => markMoving(false)}
              >
                <Button type="button" variant={toast.appearance === "undo" ? "ghost" : "outline"} size="sm" className={cn("h-7 rounded-full", toast.appearance === "undo" && "text-primary-foreground hover:bg-primary-foreground/10", classNames?.action)} onClick={runAction}>{toast.action.label}</Button>
              </motion.div>
            ) : null}
          </AnimatePresence>
                <Button ref={closeRef} type="button" variant="ghost" size="icon-sm" className={cn("-mt-1 -mr-0.5 size-7 rounded-full", toast.appearance === "undo" ? "text-primary-foreground" : "text-muted-foreground", classNames?.close)} aria-label="Dismiss notification" onClick={() => store.dismiss(id)}>
            <X width={16} height={16} strokeWidth={1.75} aria-hidden="true" />
          </Button>
        </motion.div>
      </motion.div>
    </motion.li>
  )
}

const positionClass = {
  "bottom-right": "right-6 max-[30rem]:right-0 max-[30rem]:left-0 max-[30rem]:mx-auto",
  "bottom-left": "left-6 max-[30rem]:right-0 max-[30rem]:left-0 max-[30rem]:mx-auto",
  "bottom-center": "inset-x-0 mx-auto",
}

export function ToastStack({ label = "Notifications", position = "bottom-right", contained = false, visibleToasts = 3, hotkey = true, className, classNames }: ToastStackProps) {
  const store = useStore()
  const toasts = useSyncExternalStore(store.subscribe, store.getSnapshot, getServerSnapshot)
  const reduce = !!useReducedMotion()
  const pageHidden = useSyncExternalStore(subscribeVisibility, () => document.visibilityState === "hidden", () => false)
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const [tapped, setTapped] = useState(false)
  const [dragging, setDragging] = useState(false)
  const [heights, setHeights] = useState<Record<string, number>>({})
  const regionRef = useRef<HTMLElement>(null)
  const listRef = useRef<HTMLOListElement>(null)
  const returnFocus = useRef<HTMLElement | null>(null)
  if (tapped && toasts.length === 0) setTapped(false)
  const expanded = toasts.length > 0 && (hovered || focused || tapped)
  const paused = expanded || dragging || pageHidden

  const measure = useCallback((id: string, height: number) => setHeights((current) => (current[id] === height ? current : { ...current, [id]: height })), [])
  const prune = useCallback(() => setHeights((current) => Object.fromEntries(store.getSnapshot().filter((item) => item.id in current).map((item) => [item.id, current[item.id]]))), [store])
  const toggleTap = useCallback(() => setTapped((open) => !open), [])

  const handOff = useCallback((leaving: HTMLElement, keyboard: boolean) => {
    const items = Array.from(listRef.current?.children ?? []) as HTMLElement[]
    const at = items.indexOf(leaving)
    const candidates = items.filter((item) => item !== leaving && !item.hasAttribute("inert"))
    const next = candidates.find((item) => items.indexOf(item) > at) ?? candidates[candidates.length - 1]
    const button = next?.querySelector<HTMLElement>("button")
    if (keyboard && button) button.focus()
    else if (keyboard && returnFocus.current?.isConnected) returnFocus.current.focus()
    else (document.activeElement as HTMLElement | null)?.blur()
  }, [])

  useEffect(() => {
    if (!hotkey) return
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (!event.altKey || event.metaKey || event.ctrlKey || event.code !== "KeyT") return
      const target = listRef.current?.querySelector<HTMLElement>(":scope > li:not([inert]) button")
      if (!target) return
      event.preventDefault()
      target.focus({ focusVisible: true } as FocusOptions)
      setFocused(true)
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [hotkey])

  useEffect(() => {
    if (!tapped) return
    const onDown = (event: PointerEvent) => {
      if (!regionRef.current?.contains(event.target as Node)) setTapped(false)
    }
    document.addEventListener("pointerdown", onDown)
    return () => document.removeEventListener("pointerdown", onDown)
  }, [tapped])

  const { targets, listHeight } = layoutStack(toasts, heights, expanded, visibleToasts)

  function onFocus(event: FocusEvent<HTMLElement>) {
    const from = event.relatedTarget
    if (!(from instanceof Node) || !event.currentTarget.contains(from)) returnFocus.current = from instanceof HTMLElement ? from : null
    if (focusVisible(event.target)) setFocused(true)
  }

  function onBlur(event: FocusEvent<HTMLElement>) {
    if (!(event.relatedTarget instanceof Node) || !event.currentTarget.contains(event.relatedTarget)) setFocused(false)
  }

  return (
    <section
      ref={regionRef}
      data-slot="toast-stack"
      className={cn("pointer-events-none fixed bottom-6 z-[60] w-[min(22.5rem,calc(100%-2rem))] max-[30rem]:bottom-4", contained && "absolute bottom-4 z-[2]", positionClass[position], contained && position === "bottom-right" && "right-4 max-[30rem]:right-4 max-[30rem]:left-auto", contained && position === "bottom-left" && "left-4 max-[30rem]:left-4 max-[30rem]:right-auto", className, classNames?.root)}
      aria-label={hotkey ? `${label} (Alt+T)` : label}
      aria-live="polite"
      aria-relevant="additions text"
      aria-atomic="false"
      onFocus={onFocus}
      onBlur={onBlur}
    >
      <ol
        ref={listRef}
        data-slot="toast-stack-list"
        className={cn("pointer-events-auto relative m-0 list-none p-0", classNames?.list)}
        style={{ height: listHeight }}
        data-expanded={expanded}
        onPointerEnter={(event) => {
          if (event.pointerType === "mouse") setHovered(true)
        }}
        onPointerMove={(event) => {
          if (event.pointerType === "mouse" && !hovered) setHovered(true)
        }}
        onPointerLeave={(event) => {
          if (event.pointerType === "mouse") setHovered(false)
        }}
      >
        <AnimatePresence onExitComplete={prune}>
          {toasts.map((item, index) => (
            <ToastItem key={item.id} toast={item} target={targets[index]} expanded={expanded} front={index === 0} hidden={index >= visibleToasts} paused={paused} reduce={reduce} store={store} classNames={classNames} onMeasure={measure} onDragChange={setDragging} onTap={toggleTap} onHandOff={handOff} />
          ))}
        </AnimatePresence>
      </ol>
    </section>
  )
}
